/* Productos, Inventario, Compras, Proveedores, Clientes, Gastos, Reportes, Ajustes y arranque. */
'use strict';
const provsDe=p=>[...new Set(S.catalogo.filter(c=>c.productoId===p.id).map(c=>c.proveedorId))].map(id=>IDX.prov[id]).filter(Boolean);
const dot=c=>`<span class="sw" style="background:${esc(c||'#999')}"></span>`;
const selProductos=(extraVacio)=>(extraVacio?[{v:'',t:'— Elegí un producto —'}]:[]).concat(S.productos.filter(p=>p.activo).sort((a,b)=>a.nombre.localeCompare(b.nombre)).map(p=>({v:p.id,t:p.codigo+' · '+p.nombre})));
const selProveedores=(vacio)=>(vacio?[{v:'',t:vacio}]:[]).concat(S.proveedores.slice().sort((a,b)=>a.nombre.localeCompare(b.nombre)).map(v=>({v:v.id,t:v.nombre})));
const mgPill=p=>{ const m=margen(p); return p.precio>0?(m<30?pill(m<20?'bad':'warn',fmt(m,0)+'%'):fmt(m,0)+'%'):pill('mute','—'); };

/* ================= PRODUCTOS ================= */
VIEWS.productos=function(){ const f=UI.f.prod;
  return `${encab('Productos','',`<button class="btn pri" data-act="prod-nuevo">Nuevo producto</button><button class="btn" data-act="prod-precios">Actualizar precios</button><details class="mnu"><summary class="btn" aria-label="Más acciones">Más<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><path d="M6 9l6 6 6-6"/></svg></summary><div><button data-act="prod-etiquetas">Imprimir etiquetas de precio</button><button data-act="prod-unidad">Unidad por categoría</button><button data-act="prod-import">Importar productos</button><button data-act="prod-export">Exportar productos</button></div></details>`)}
  <div class="filters"><label class="field">Buscar<span class="srch">${SVG(LUPA_D)}<input data-bind="f.prod.q" value="${esc(f.q)}" placeholder="Nombre, código o código de barras"></span></label>
   <label class="field">Categoría<select data-bind="f.prod.cat"><option value="">Todas</option>${opts(cats(),f.cat)}</select></label>
   <label class="field">Proveedor<select data-bind="f.prod.prov">${opts(selProveedores('Todos'),f.prov)}</select></label>
   <label class="field">Ver<select data-bind="f.prod.ver">${opts([{v:'',t:'Todos'},{v:'sin',t:'Sin stock'},{v:'bajo',t:'Stock bajo o sin stock'},{v:'precio',t:'Precio desactualizado'},{v:'margen',t:'Margen bajo (menos de 20%)'}],f.ver)}</select></label>
   <label class="field">Estado<select data-bind="f.prod.est">${opts([{v:'activos',t:'Activos'},{v:'inactivos',t:'Inactivos'},{v:'todos',t:'Todos'}],f.est)}</select></label></div><div id="res"></div>`; };
FILL.productos=function(){ const r=$('#res'); if(!r) return; const f=UI.f.prod; const q=f.q.trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'');
  const l=S.productos.filter(p=>{ if(f.est==='activos'&&!p.activo) return false; if(f.est==='inactivos'&&p.activo) return false; if(f.cat&&p.categoria!==f.cat) return false;
    if(f.prov&&!S.catalogo.some(c=>c.productoId===p.id&&String(c.proveedorId)===String(f.prov))) return false;
    if(q&&!(p.nombre.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').includes(q)||p.codigo.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').includes(q)||(p.barras||'').includes(q)||(p.categoria||'').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').includes(q))) return false;
    const s=stockDe(p.id); if(f.ver==='sin'&&s>0) return false; if(f.ver==='bajo'&&s>p.minimo) return false; if(f.ver==='margen'&&!(p.precio>0&&margen(p)<20)) return false;
    if(f.ver==='precio'){ const d=diasPrecio(p); if(!(d!=null&&d>S.config.diasPrecio)) return false; } return true; }).sort((a,b)=>a.nombre.localeCompare(b.nombre));
  const sinS=l.filter(p=>stockDe(p.id)<=0).length, bajoS=l.filter(p=>{ const s=stockDe(p.id); return s>0&&s<=p.minimo; }).length, valC=l.reduce((a,p)=>a+Math.max(0,stockDe(p.id))*p.costo,0);
  const act=S.productos.filter(p=>p.activo), nSin=act.filter(p=>stockDe(p.id)<=0).length, nBajo=act.filter(p=>stockDe(p.id)<=p.minimo).length;
  r.innerHTML=franja('prod-ver',f.ver,[{v:'',k:'Productos',n:act.length},{v:'sin',k:'Sin stock',n:nSin,cls:nSin?'bad':''},{v:'bajo',k:'Stock bajo o sin stock',n:nBajo,cls:nBajo?'warn':''},{v:'precio',k:'Stock a costo',n:money(valC),cls:'nofil'}])+(l.length?`<div class="tw"><table><thead><tr><th>Producto</th><th class="n">Stock</th><th class="n">Costo</th><th class="n">Precio</th><th class="c">Margen</th><th>Proveedor</th><th>Alerta</th></tr></thead><tbody>${l.map(p=>{ const s=stockDe(p.id); const d=diasPrecio(p); const pv=provsDe(p);
    return `<tr class="click ${p.activo?'':'off'}" data-act="prod-edit" data-id="${p.id}"><td><b>${esc(p.nombre)}</b><div class="sm muted">${esc(p.codigo)}${p.categoria?' · '+esc(p.categoria):''}</div></td><td class="n"><div class="stk ${s<=0?'bad':s<=p.minimo?'warn':''}"><b>${qtyTxt(p,s)}</b><span class="mtr"><i style="width:${Math.max(0,Math.min(100,s/Math.max(p.minimo*3,0.001)*100))}%"></i><u style="left:${Math.min(100,100/3)}%"></u></span><small>mín. ${qtyTxt(p,p.minimo)}</small></div></td><td class="n">${money2(p.costo)}</td><td class="n b">${money2(p.precio)}</td><td class="c">${mgPill(p)}</td><td>${pv.length?pv.map(v=>dot(v.color)+esc(v.nombre)).join('<br>'):'<span class="muted">—</span>'}</td>
    <td>${!p.activo?pill('mute','Inactivo'):s<=0?pill('bad','Sin stock'):s<=p.minimo?'<span class="est warn">Stock bajo</span>':''}${d!=null&&d>S.config.diasPrecio?' '+pill('info','Precio viejo'):''}</td></tr>`; }).join('')}</tbody></table></div>`:vacioHtml(S.productos.length?'No hay productos con esos filtros.':'Todavía no hay productos. Creá el primero o importá una lista.')); };
AFTER.productos=()=>FILL.productos();
function camposProducto(p){ const nuevo=!p;
  const c=[{n:'nombre',l:'Nombre',t:'text',req:true,full:true},{n:'codigo',mas:1,l:'Código interno',t:'text',ro:!nuevo,ph:'Se genera solo'},{n:'barras',mas:1,l:'Código de barras',t:'text',ph:'Opcional'},
    {n:'categoria',l:'Categoría',t:'text',list:cats().concat(RUBROS[S.config.rubro]?RUBROS[S.config.rubro].cats:[]).filter((x,i,a)=>a.indexOf(x)===i)}];
  if(S.config.peso) c.push({n:'unidad',l:'Se vende por',t:'select',o:[{v:'u',t:'Unidad'},{v:'kg',t:'Peso (kg)'}]});
  if(S.config.peso||S.config.balanza.on) c.push({n:'plu',mas:1,l:'PLU de balanza',t:'text',ph:'Ej. 123',hint:'El número del producto en la balanza, para leer sus etiquetas.'});
  c.push({n:'costo',l:'Costo ($)',t:'num',min:0,live:'margen'},{n:'precio',l:'Precio de venta ($)',t:'num',min:0,live:'margen',hint:''},{n:'minimo',l:'Stock mínimo',t:'num',min:0});
  if(nuevo){ c.push({n:'stock',l:'Stock inicial',t:'num',min:0},{n:'proveedor',l:'Proveedor (opcional)',t:'select',o:selProveedores('(ninguno)')}); }
  c.push({n:'activo',l:'Producto activo',t:'check'},{n:'notas',mas:1,l:'Notas',t:'area',full:true}); return c; }
LIVE.margen=()=>{ const c=num($('#f_costo').value),p=num($('#f_precio').value),h=$('#h_precio'); if(!h) return; h.textContent=(p>0&&c!=null)?'Margen: '+fmt((p-c)/p*100,1)+'%  ·  Ganancia por unidad: '+money2(p-c):''; };
ACT['prod-ver']=el=>{ UI.f.prod.ver=el.dataset.v; render(); };
ACT['prod-nuevo']=()=>prodForm(null);
ACT['prod-edit']=el=>prodForm(prod(+el.dataset.id));
function prodForm(p){ const nuevo=!p; const vals=p?Object.assign({},p):{unidad:'u',activo:true,costo:'',precio:'',minimo:''};
  const foot=p?`<button class="btn sm" data-act="prod-mover" data-id="${p.id}" type="button">Mover stock</button><button class="btn sm" data-act="prod-hist" data-id="${p.id}" type="button">Historial de precios</button><button class="btn sm bad" data-act="prod-del" data-id="${p.id}" type="button">Eliminar</button><span class="grow"></span>`:'';
  formModal(nuevo?'Nuevo producto':'Editar producto',camposProducto(p),vals,d=>{
    if(d.barras&&S.productos.some(x=>x.barras&&x.barras===d.barras&&(!p||x.id!==p.id))) throw new Error('Ese código de barras ya está en otro producto.');
    if(!nuevo&&p.unidad==='kg'&&d.unidad==='u'&&Math.abs(stockDe(p.id)-Math.round(stockDe(p.id)))>0.0005) throw new Error('No se puede pasar a «por unidad»: tiene '+qtyTxt(p,stockDe(p.id))+' en stock. Primero ajustá el stock a un número entero desde «Mover stock».');
    if(!nuevo&&Math.abs(p.costo-d.costo)>=0.005) S.historial.push({id:sig('H'),fecha:hoy(),productoId:p.id,proveedorId:0,precio:d.costo,origen:'Ficha del producto'});
    const q=guardarProducto(Object.assign({},d,{codigo:nuevo?'':p.codigo,unidad:d.unidad||'u'}),p?p.id:null);
    if(nuevo){ if(d.stock>0) mov(q.id,'Entrada',d.stock,'Stock inicial'); if(d.proveedor&&d.costo>0) registrarPrecio(q.id,+d.proveedor,d.costo,hoy(),'Ficha del producto'); }
    guardar(); cerrar(); refrescar(); toast(nuevo?'Producto creado':'Producto guardado'); },{wide:true,foot});
  LIVE.margen(); }
ACT['prod-del']=el=>{ const p=prod(+el.dataset.id);
  if(S.ventas.some(v=>v.items.some(i=>i.productoId===p.id))||S.compras.some(c=>c.items.some(i=>i.productoId===p.id))){ toast('«'+p.nombre+'» tiene ventas o compras. Para no perder el historial, marcalo como inactivo.',true); return; }
  confirmar('¿Eliminar «'+esc(p.nombre)+'» con sus movimientos y precios? No se puede deshacer.',()=>{ S.productos=S.productos.filter(x=>x.id!==p.id); S.movimientos=S.movimientos.filter(x=>x.productoId!==p.id); S.lotes=S.lotes.filter(x=>x.productoId!==p.id); S.catalogo=S.catalogo.filter(x=>x.productoId!==p.id); S.historial=S.historial.filter(x=>x.productoId!==p.id); indexar(); guardar(); refrescar(); toast('Producto eliminado'); },'Eliminar'); };
ACT['prod-mover']=el=>moverForm(prod(+el.dataset.id));
ACT['prod-hist']=el=>{ const p=prod(+el.dataset.id); const h=S.historial.filter(x=>x.productoId===p.id).sort((a,b)=>a.fecha<b.fecha?-1:a.fecha>b.fecha?1:a.id-b.id); const ant={};
  const filas=h.map(x=>{ const k=x.proveedorId; const v=ant[k]!=null&&ant[k]>0?(x.precio-ant[k])/ant[k]*100:null; ant[k]=x.precio; return {x,v}; }).reverse();
  abrir('Historial de precios · '+p.nombre,filas.length?`<div class="tw"><table><thead><tr><th>Fecha</th><th>Proveedor</th><th class="n">Precio</th><th class="n">Variación</th><th>Origen</th></tr></thead><tbody>${filas.map(({x,v})=>`<tr><td>${fechaTxt(x.fecha)}</td><td>${esc(x.proveedorId?provNom(x.proveedorId):'Ficha')}</td><td class="n">${money2(x.precio)}</td><td class="n ${v>0?'dn':v<0?'up':''}">${v==null?'—':(v>0?'+':'')+fmt(v,1)+'%'}</td><td>${esc(x.origen)}</td></tr>`).join('')}</tbody></table></div>`:vacioHtml('Todavía no hay cambios de precio registrados.'),{wide:true,foot:'<button class="btn pri" data-act="cerrar">Cerrar</button>'}); };

/* actualización masiva de precios (inflación) */
function sinCostoEn(d){ return d.modo==='margen'?S.productos.filter(p=>p.activo&&!(p.costo>0)&&(!d.cat||p.categoria===d.cat)&&(!d.prov||S.catalogo.some(c=>c.productoId===p.id&&String(c.proveedorId)===String(d.prov)))).length:0; }
function planPrecios(d){ const m=d.modo; const r=num(d.redondeo)||0; const v=d.valor||0;
  const rd=x=>r>0?Math.round(x/r)*r:r2(x);
  return S.productos.filter(p=>p.activo&&(m!=='margen'||p.costo>0)&&(!d.cat||p.categoria===d.cat)&&(!d.prov||S.catalogo.some(c=>c.productoId===p.id&&String(c.proveedorId)===String(d.prov)))).map(p=>{
    let c=p.costo,pr=p.precio;
    if(m==='pct'){ if(d.ajustar!=='precio') c=r2(p.costo*(1+v/100)); if(d.ajustar!=='costo') pr=rd(p.precio*(1+v/100)); }
    else { pr=v<100?rd(p.costo/(1-v/100)):p.precio; }
    return {p,c,pr}; }); }
function leerPrecios(){ const f=$('#frm'); return {cat:f.elements.cat.value,prov:f.elements.prov.value,modo:f.elements.modo.value,ajustar:f.elements.ajustar.value,valor:num(f.elements.valor.value)||0,redondeo:f.elements.redondeo.value}; }
LIVE.prbulk=()=>{ const d=leerPrecios(); const pl=planPrecios(d); const e=$('#prv'); if(!e) return; const sc=sinCostoEn(d);
  e.innerHTML=(sc?`<div class="al warn mb8"><div class="grow"><b>${sc} producto${sc>1?'s':''} sin costo cargado</b> no se ${sc>1?'tocan':'toca'}: sin costo no se puede calcular el margen.</div></div>`:'')+(d.modo==='pct'&&d.valor<=-100?'<div class="al bad mb8"><div class="grow">Bajar 100% o más deja los precios en cero.</div></div>':'')+(pl.length?`<p class="sm"><b>${pl.length}</b> producto${pl.length>1?'s':''} se van a modificar. Ejemplos:</p><div class="tw"><table><thead><tr><th>Producto</th><th class="n">Costo</th><th class="n">Precio</th><th class="c">Margen</th></tr></thead><tbody>${pl.slice(0,5).map(x=>`<tr><td>${esc(x.p.nombre)}</td><td class="n">${money2(x.p.costo)} → ${money2(x.c)}</td><td class="n">${money2(x.p.precio)} → <b>${money2(x.pr)}</b></td><td class="c">${x.pr>0?fmt((x.pr-x.c)/x.pr*100,0)+'%':'—'}</td></tr>`).join('')}</tbody></table></div>`:'<p class="sm muted">No hay productos con ese alcance.</p>'); };
ACT['prod-precios']=()=>{ const campos=[{n:'cat',l:'Categoría',t:'select',o:[{v:'',t:'Todas'}].concat(cats()),live:'prbulk'},{n:'prov',l:'Proveedor',t:'select',o:selProveedores('Todos'),live:'prbulk'},
  {n:'modo',l:'Cómo ajustar',t:'select',o:[{v:'pct',t:'Aumentar o bajar un porcentaje'},{v:'margen',t:'Fijar margen objetivo (sobre el costo actual)'}],live:'prbulk'},{n:'ajustar',l:'Qué ajustar (modo porcentaje)',t:'select',o:[{v:'ambos',t:'Costo y precio de venta'},{v:'precio',t:'Solo precio de venta'},{v:'costo',t:'Solo costo'}],live:'prbulk'},
  {n:'valor',l:'Porcentaje (%) o margen objetivo (%)',t:'num',live:'prbulk',ph:'Ej: 8'},{n:'redondeo',l:'Redondear precios de venta a',t:'select',o:[{v:'0',t:'Centavos (sin redondeo)'},{v:'10',t:'$10'},{v:'50',t:'$50'},{v:'100',t:'$100'}],live:'prbulk'}];
  formModal('Actualizar precios en bloque',campos,{modo:'pct',ajustar:'ambos',redondeo:'10'},d=>{ const dd=leerPrecios(); if(!dd.valor) throw new Error('Ingresá el porcentaje.'); if(dd.modo==='pct'&&dd.valor<=-100) throw new Error('No se puede bajar 100% o más: los precios quedarían en cero.'); if(dd.modo==='margen'&&(dd.valor<=0||dd.valor>=100)) throw new Error('El margen objetivo tiene que estar entre 0 y 100.');
    const pl=planPrecios(dd); if(!pl.length) throw new Error('No hay productos con ese alcance.'); pl.forEach(x=>{ x.p.costo=x.c; x.p.precio=x.pr; }); guardar(); cerrar(); refrescar(); toast(pl.length+' productos actualizados'); },{wide:true,okText:'Aplicar cambios',extra:'<div id="prv" class="mt12"></div>'}); LIVE.prbulk(); };
ACT['prod-unidad']=()=>{ if(!cats().length){ toast('Todavía no hay categorías cargadas.',true); return; }
  formModal('Unidad de venta por categoría',[{n:'cat',l:'Categoría',t:'select',o:cats(),full:true},{n:'unidad',l:'Se vende por',t:'select',o:[{v:'kg',t:'Peso (kg)'},{v:'u',t:'Unidad'}],full:true}],{unidad:'kg'},d=>{ let n=0; const salt=[]; S.productos.forEach(p=>{ if(p.categoria===d.cat&&p.unidad!==d.unidad){ if(d.unidad==='u'&&Math.abs(stockDe(p.id)-Math.round(stockDe(p.id)))>0.0005){ salt.push(p.nombre); return; } p.unidad=d.unidad; n++; } }); guardar(); cerrar(); refrescar(); toast(n+' producto'+(n===1?'':'s')+' actualizado'+(n===1?'':'s')+(salt.length?'. No se cambi'+(salt.length===1?'ó':'aron')+' '+salt.length+' con stock en kilos con decimales: '+salt.slice(0,3).join(', ')+(salt.length>3?'…':''):''),salt.length>0); },{okText:'Aplicar'}); };
ACT['prod-export']=()=>{ const rows=S.productos.map(p=>[p.codigo,p.nombre,p.categoria,p.unidad,fmt(p.costo,2).replace(/\./g,''),fmt(p.precio,2).replace(/\./g,''),fmt(stockDe(p.id),3).replace(/\./g,''),fmt(p.minimo,3).replace(/\./g,''),p.barras,(provsDe(p)[0]||{}).nombre||'']);
  descargar('productos_'+hoy()+'.csv',aCSV(['codigo','nombre','categoria','unidad','costo','precio','stock','minimo','barras','proveedor'],rows)); };
ACT['prod-import']=()=>{ abrir('Importar productos',`<p class="mt0">Subí un archivo CSV (podés guardarlo desde Excel con «Guardar como CSV»). Los productos con el mismo código se <b>actualizan</b> y los nuevos se crean. Columnas reconocidas: <span class="sm muted">codigo, nombre, categoria, unidad (u o kg), costo, precio, stock, minimo, barras, proveedor</span>. Solo «nombre» es obligatoria.</p>
  <input type="file" id="impf" accept=".csv,.txt"><div id="impr" class="sm mt12"></div>`,{foot:`<button class="btn" id="modelo">Descargar modelo</button><button class="btn pri" data-act="cerrar">Cerrar</button>`});
  $('#modelo').onclick=()=>descargar('modelo_productos.csv',aCSV(['codigo','nombre','categoria','unidad','costo','precio','stock','minimo','barras','proveedor'],[['FIA010','Jamón cocido natural','Fiambres','kg','9800','14500','12','3','','Frigorífico Don Pepe']]));
  $('#impf').onchange=e=>{ const f=e.target.files[0]; if(!f) return; const rd=new FileReader(); rd.onload=()=>{ try{ const r=importarProductosCSV(String(rd.result)); refrescar(); $('#impr').innerHTML=`<b class="up">Listo.</b> Productos nuevos: ${r.nuevos}. Actualizados: ${r.act}.${r.errores.length?'<br><span class="dn">'+r.errores.slice(0,8).map(esc).join('<br>')+'</span>':''}`; }catch(err){ $('#impr').innerHTML='<span class="dn">'+esc(err.message)+'</span>'; } }; rd.readAsText(f,'utf-8'); }; };

/* ================= INVENTARIO ================= */
VIEWS.inventario=function(){ const v=S.config.venc; if(!UI.invTab||(!v&&UI.invTab==='lotes')) UI.invTab=v?'lotes':'mov';
  const t=tabs((v?[['lotes','Vencimientos']]:[]).concat([['mov','Movimientos'],['recuento','Recuento']]),UI.invTab,'tab-inv'); const f=UI.f.mov;
  return `${encab('Inventario','',`<button class="btn pri" data-act="mov-nuevo">Registrar movimiento</button>`)}${t}
  ${UI.invTab==='mov'?`<div class="filters"><label class="field">Buscar<span class="srch">${SVG(LUPA_D)}<input data-bind="f.mov.q" value="${esc(f.q)}" placeholder="Producto o motivo"></span></label><label class="field">Tipo<select data-bind="f.mov.tipo">${opts([{v:'',t:'Todos'},'Entrada','Compra','Venta','Salida','Merma','Ajuste'],f.tipo)}</select></label><label class="field">Desde<input type="date" data-bind="f.mov.desde" value="${esc(f.desde)}"></label></div>`:''}<div id="res"></div>`; };
ACT['tab-inv']=el=>{ UI.invTab=el.dataset.t; render(); };
FILL.inventario=function(){ const r=$('#res'); if(!r) return;
  if(UI.invTab==='lotes'){ const l=S.lotes.filter(x=>x.cant>0&&x.vence&&prod(x.productoId)).sort((a,b)=>a.vence<b.vence?-1:1); const venc=l.filter(x=>difDias(x.vence,hoy())<0).length, porv=l.filter(x=>{const d=difDias(x.vence,hoy());return d>=0&&d<=S.config.diasVence;}).length;
    const grupos=[['Vencidos',x=>difDias(x.vence,hoy())<0,'bad'],['Esta semana',x=>{const d=difDias(x.vence,hoy());return d>=0&&d<=7;},'warn'],['Este mes',x=>{const d=difDias(x.vence,hoy());return d>7&&d<=31;},''],['Más adelante',x=>difDias(x.vence,hoy())>31,'']];
    const fila=x=>{ const p=prod(x.productoId),e=estadoVence(x); return `<div class="fila"><span class="pt ${e.k}" aria-hidden="true"></span><div class="fm"><b>${esc(p.nombre)}</b><span>Lote ${esc(x.lote)} · vence ${fechaTxt(x.vence)} · ${e.t}</span></div><div class="fn"><b>${qtyTxt(p,x.cant)}</b><span>${money(x.cant*p.costo)} a costo</span></div><div class="fa">${e.d<=S.config.diasVence?`<button class="btn sm" data-act="lote-baja" data-id="${x.id}">${e.d<0?'Dar de baja':'Merma'}</button>`:''}</div></div>`; };
    r.innerHTML=franja('',null,[{v:'a',k:'Lotes vencidos',n:venc,cls:(venc?'bad':'')+' nofil'},{v:'b',k:'Por vencer en '+S.config.diasVence+' días',n:porv,cls:(porv?'warn':'')+' nofil'},{v:'c',k:'Valor en riesgo, a costo',n:money(l.filter(x=>difDias(x.vence,hoy())<=S.config.diasVence).reduce((a,x)=>a+x.cant*(prod(x.productoId).costo),0)),cls:'nofil'}])+
      (l.length?grupos.map(([t,fn,k])=>{ const g=l.filter(fn); return g.length?`<section class="grupo"><h2 class="gh ${k}">${t}<span class="cnt">${g.length}</span></h2><div class="filas">${g.map(fila).join('')}</div></section>`:''; }).join(''):vacioHtml('No hay lotes con vencimiento cargado. Cargá la fecha de vencimiento al registrar una compra o una entrada.')); return; }
  if(UI.invTab==='recuento'){ const l=S.productos.filter(p=>p.activo).sort((a,b)=>(a.categoria||'').localeCompare(b.categoria||'')||a.nombre.localeCompare(b.nombre));
    r.innerHTML=`<p class="sm muted mt0">Contá lo que hay en el local y escribilo en «Contado». Solo se ajustan los que completes y que difieran del sistema. Para productos al peso usá kg.</p><div class="tw"><table><thead><tr><th>Producto</th><th class="n">En sistema</th><th class="n" style="width:140px">Contado</th><th class="n">Diferencia</th></tr></thead><tbody>${l.map(p=>`<tr><td>${esc(p.nombre)}<div class="sm muted">${esc(p.categoria||'')}</div></td><td class="n">${qtyTxt(p,stockDe(p.id))}</td><td class="n"><input id="rc_${p.id}" data-live="rc-dif" data-id="${p.id}" inputmode="decimal" style="text-align:right"></td><td class="n" id="rd_${p.id}"></td></tr>`).join('')}</tbody></table></div><div class="bar mt12"><button class="btn pri" data-act="rc-aplicar">Aplicar ajustes</button></div>`; return; }
  const f=UI.f.mov,q=f.q.trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,''); const l=S.movimientos.filter(m=>(!f.tipo||m.tipo===f.tipo)&&(!f.desde||m.fecha>=f.desde)&&(!q||((prod(m.productoId)||{}).nombre||'').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').includes(q)||(m.motivo||'').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').includes(q))).sort((a,b)=>b.id-a.id).slice(0,300);
  const col={Entrada:'good',Compra:'good',Venta:'info',Salida:'warn',Merma:'bad',Ajuste:'mute'};
  r.innerHTML=l.length?`<div class="tw"><table><thead><tr><th>Fecha</th><th>Producto</th><th>Tipo</th><th class="n">Cantidad</th><th>Motivo</th></tr></thead><tbody>${l.map(m=>{ const p=prod(m.productoId); return `<tr><td>${fechaTxt(m.fecha)} ${m.hora||''}</td><td>${esc(p?p.nombre:'(borrado)')}</td><td>${pill(col[m.tipo]||'mute',m.tipo)}</td><td class="n b ${m.cant<0?'dn':'up'}">${m.cant>0?'+':''}${qtyTxt(p,m.cant)}</td><td>${esc(m.motivo)}</td></tr>`; }).join('')}</tbody></table></div>`:vacioHtml('No hay movimientos con esos filtros.'); };
AFTER.inventario=()=>FILL.inventario();
LIVE['rc-dif']=el=>{ const p=prod(+el.dataset.id); const v=numCant(p,el.value); const c=$('#rd_'+p.id); if(!c) return; if(v==null){ c.textContent=''; return; } const d=r3(v-stockDe(p.id)); c.innerHTML=Math.abs(d)<0.0001?'<span class="muted">Igual</span>':`<b class="${d<0?'dn':'up'}">${d>0?'+':''}${fmt(d,3).replace(/,?0+$/,'')}</b>`; };
ACT['rc-aplicar']=()=>{ let n=0; S.productos.forEach(p=>{ const el=$('#rc_'+p.id); if(!el||el.value.trim()==='') return; const v=numCant(p,el.value); if(v==null||v<0) return; if(moverStock(p.id,'Ajuste',v,'Recuento de inventario')) n++; }); indexar(); refrescar(); toast(n?n+' ajuste'+(n>1?'s':'')+' aplicado'+(n>1?'s':''):'No había diferencias para ajustar'); };
ACT['lote-baja']=el=>{ const l=S.lotes.find(x=>x.id===+el.dataset.id); const p=prod(l.productoId); confirmar('¿Dar de baja '+qtyTxt(p,l.cant)+' de «'+esc(p.nombre)+'» (lote '+esc(l.lote)+')? Se registra como merma valorizada a costo ('+money(l.cant*p.costo)+').',()=>{ bajaLote(l.id); indexar(); refrescar(); toast('Baja registrada'); },'Dar de baja'); };
ACT['mov-nuevo']=()=>moverForm(null);
function moverForm(p){ const campos=[{n:'pid',l:'Producto',t:'select',o:selProductos(!p),req:true,full:true},{n:'tipo',l:'Tipo de movimiento',t:'select',o:[{v:'Entrada',t:'Entrada (suma stock)'},{v:'Salida',t:'Salida (resta stock)'},{v:'Merma',t:'Merma o rotura (resta y se valoriza)'},{v:'Ajuste',t:'Ajuste (stock real contado)'}]},
  {n:'cant',l:'Cantidad (kg si se vende al peso)',t:'num',req:true,min:0},{n:'motivo',l:'Motivo',t:'text',list:['Reposición','Devolución','Rotura','Vencimiento','Uso interno','Recuento de inventario']},{n:'fecha',l:'Fecha',t:'date'}];
  if(S.config.venc) campos.push({n:'vence',l:'Vencimiento (solo entradas)',t:'date'},{n:'lote',l:'Lote (opcional)',t:'text'});
  formModal('Movimiento de stock',campos,{pid:p?p.id:'',fecha:hoy(),tipo:'Entrada'},d=>{ const pid=+d.pid; if(!pid) throw new Error('Elegí un producto.'); d.cant=numCant(prod(pid),$('#frm').elements.cant.value); if(d.cant==null||d.cant<0) throw new Error('Revisá la cantidad.'); if(d.tipo!=='Ajuste'&&d.cant<=0) throw new Error('La cantidad tiene que ser mayor a 0.');
    if(d.tipo==='Entrada'&&S.config.venc&&d.vence) S.lotes.push({id:sig('L'),productoId:pid,lote:d.lote||'Manual',vence:d.vence,cant:d.cant,cantInicial:d.cant,compraId:0,fecha:d.fecha||hoy()});
    const ok=moverStock(pid,d.tipo,d.cant,d.motivo,d.fecha||hoy()); indexar(); cerrar(); refrescar(); toast(ok===false?'El stock ya coincidía, no hubo cambios':'Movimiento registrado'); }); }

/* ================= COMPRAS ================= */
VIEWS.compras=function(){ const t=tabs([['lista','Compras'],['pedido','Pedido sugerido']],UI.compTab,'tab-comp'); const f=UI.f.comp;
  return `${encab('Compras','',`<button class="btn pri" data-act="compra-nueva">Nueva compra</button>`)}${t}${UI.compTab==='lista'?`<div class="filters"><label class="field">Buscar<span class="srch">${SVG(LUPA_D)}<input data-bind="f.comp.q" value="${esc(f.q)}" placeholder="N° o proveedor"></span></label><label class="field">Desde<input type="date" data-bind="f.comp.desde" value="${esc(f.desde)}"></label></div>`:''}<div id="res"></div>`; };
ACT['tab-comp']=el=>{ UI.compTab=el.dataset.t; render(); };
FILL.compras=function(){ const r=$('#res'); if(!r) return;
  if(UI.compTab==='pedido'){ r.innerHTML=pedidoHtml(); return; }
  const f=UI.f.comp,q=f.q.trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,''); const l=S.compras.filter(c=>(!f.desde||c.fecha>=f.desde)&&(!q||String(c.id)===q||provNom(c.proveedorId).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').includes(q))).sort((a,b)=>b.id-a.id);
  const pend=S.compras.filter(c=>c.estado!=='Anulada'&&c.pago==='Pendiente').reduce((a,c)=>a+c.total,0);
  const mes=hoy().slice(0,7), delMes=S.compras.filter(c=>c.estado!=='Anulada'&&c.fecha.startsWith(mes));
  r.innerHTML=franja('',null,[{v:'a',k:'A pagar a proveedores',n:money(pend),cls:(pend>0?'warn':'')+' nofil'},{v:'b',k:'Comprado este mes',n:money(delMes.reduce((a,c)=>a+c.total,0)),cls:'nofil'},{v:'c',k:'Compras este mes',n:delMes.length,cls:'nofil'}])+(l.length?`<div class="filas">${l.map(c=>{ const v=IDX.prov[c.proveedorId]||{}; return `<div class="fila click ${c.estado==='Anulada'?'off':''}" data-act="compra-ver" data-id="${c.id}" style="--pc:${esc(v.color||'#999')}"><span class="pv" aria-hidden="true"></span><div class="fm"><b>${esc(provNom(c.proveedorId))}</b><span>#${c.id} · ${fechaTxt(c.fecha)} · ${c.items.length} ítem${c.items.length===1?'':'s'}${Math.abs(c.costoReal-c.total)>0.5?' · costo real '+money(c.costoReal):''}</span></div><div class="fe">${c.estado==='Anulada'?pill('bad','Anulada'):c.pago==='Pendiente'?'<span class="est warn">A pagar</span>':`<span class="muted sm">${esc(c.pago)}</span>`}</div><div class="fn"><b>${money(c.total)}</b></div></div>`; }).join('')}</div>`:vacioHtml('Todavía no registraste compras.')); };
AFTER.compras=()=>FILL.compras();
ACT['compra-ver']=el=>{ const c=S.compras.find(x=>x.id===+el.dataset.id);
  abrir('Compra #'+c.id+' · '+fechaTxt(c.fecha),`<p class="mt0"><b>${esc(provNom(c.proveedorId))}</b> ${c.estado==='Anulada'?pill('bad','Anulada'):''} ${c.pago==='Pendiente'?pill('warn','Pendiente de pago'):'· pago: '+esc(c.pago)+(c.fechaPago?' el '+fechaTxt(c.fechaPago):'')}</p>${c.corregidaPor?`<div class="al info mb12"><div class="grow">Se corrigió: la reemplaza la <b>compra #${c.corregidaPor}</b>.</div><button class="btn sm" data-act="compra-ver" data-id="${c.corregidaPor}">Ver</button></div>`:''}${c.corrige?`<div class="al info mb12"><div class="grow">Es la corrección de la <b>compra #${c.corrige}</b>, que quedó anulada.</div></div>`:''}<div class="tw"><table><thead><tr><th>Producto</th><th class="n">Cantidad</th><th class="n">Precio</th><th class="n">Subtotal</th><th>Vence</th></tr></thead><tbody>${c.items.map(i=>{ const p=prod(i.productoId)||{nombre:'(borrado)'}; return `<tr><td>${esc(p.nombre)}</td><td class="n">${qtyTxt(p,i.cant)}</td><td class="n">${money2(i.costo)}</td><td class="n">${money2(i.cant*i.costo)}</td><td>${i.vence?fechaTxt(i.vence):'—'}</td></tr>`; }).join('')}</tbody></table></div>
  <div class="tw mt12"><table><tbody><tr><td>Neto</td><td class="n">${money2(c.neto)}</td></tr><tr><td>IVA ${fmt(c.ivaPct,1)}% ${c.ivaRec?'(recuperable)':'(parte del costo)'}</td><td class="n">${money2(c.iva)}</td></tr><tr><td>Flete</td><td class="n">${money2(c.flete)}</td></tr><tr><td>Otros gastos</td><td class="n">${money2(c.otros)}</td></tr><tr class="tot"><td>Total pagado</td><td class="n">${money2(c.total)}</td></tr><tr class="tot"><td>Costo real</td><td class="n">${money2(c.costoReal)}</td></tr></tbody></table></div>${c.obs?`<p class="sm muted">Obs.: ${esc(c.obs)}</p>`:''}`,
  {wide:true,foot:`${c.estado!=='Anulada'?`<button class="btn bad" data-act="compra-anular" data-id="${c.id}">Anular compra</button><button class="btn" data-act="compra-corregir" data-id="${c.id}">Corregir</button>`:''}${c.estado!=='Anulada'&&c.pago==='Pendiente'?`<button class="btn" data-act="compra-pagar" data-id="${c.id}">Marcar como pagada</button>`:''}<button class="btn pri" data-act="cerrar">Cerrar</button>`}); };
ACT['compra-corregir']=el=>{ const c=S.compras.find(x=>x.id===+el.dataset.id); if(!c||c.estado==='Anulada') return;
  modalCompra({reemplaza:c.id,fecha:c.fecha,proveedorId:c.proveedorId,pago:c.pago,ivaPct:c.ivaPct,ivaRec:c.ivaRec,flete:c.flete,otros:c.otros,obs:c.obs,items:c.items.map(i=>({pid:i.productoId,cant:i.cant,costo:i.costo,vence:i.vence||''}))}); };
ACT['compra-anular']=el=>{ const id=+el.dataset.id, c=S.compras.find(x=>x.id===id); const neg=c.items.map(i=>({p:prod(i.productoId),q:r3(stockDe(i.productoId)-i.cant)})).filter(x=>x.p&&x.q<-0.0005);
  confirmar('¿Anular la compra #'+id+'? Se descuenta del stock lo que había sumado y se dan de baja sus lotes. El historial de precios se conserva.'+(neg.length?'<div class="al warn mt12"><div class="grow"><b>Parte de esta mercadería ya se vendió.</b> El stock va a quedar en negativo: '+neg.map(x=>esc(x.p.nombre)+' ('+qtyTxt(x.p,x.q)+')').join(', ')+'. Después corregilo con un recuento.</div></div>':''),()=>{ anularCompra(id); indexar(); refrescar(); toast('Compra anulada'); },'Anular compra'); };
ACT['compra-pagar']=el=>{ const c=S.compras.find(x=>x.id===+el.dataset.id); formModal('Registrar pago de la compra #'+c.id,[{n:'medio',l:'Medio de pago',t:'select',o:['Efectivo','Transferencia']},{n:'fecha',l:'Fecha de pago',t:'date'}],{fecha:hoy()},d=>{ c.pago=d.medio; c.fechaPago=d.fecha||hoy(); guardar(); cerrar(); refrescar(); toast('Pago registrado'); }); };

/* nueva compra */
let CD=null;
function filaCompra(it,i){ return `<tr data-row="${i}"><td style="min-width:200px"><select data-live="cmp-row" data-i="${i}" data-k="pid" aria-label="Producto">${opts(selProductos(true),it.pid)}</select></td><td style="width:90px"><input data-live="cmp-row" data-i="${i}" data-k="cant" value="${esc(it.cant)}" inputmode="decimal" aria-label="Cantidad"></td><td style="width:110px"><input data-live="cmp-row" data-i="${i}" data-k="costo" value="${esc(it.costo)}" inputmode="decimal" aria-label="Costo unitario"></td>${S.config.venc?`<td style="width:140px"><input type="date" data-live="cmp-row" data-i="${i}" data-k="vence" value="${esc(it.vence)}" aria-label="Vencimiento"></td>`:''}<td class="n nw" id="cs_${i}"></td><td><button class="btn sm ghost" data-act="cmp-del" data-i="${i}" aria-label="Quitar">✕</button></td></tr>`; }
function pintarFilasCompra(){ $('#cmprows').innerHTML=CD.items.map(filaCompra).join(''); totalCompra(); }
function leerItemsCompra(){ return CD.items.map(i=>({productoId:+i.pid||0,cant:numCant(prod(+i.pid),i.cant)||0,costo:num(i.costo)||0,vence:i.vence||null,lote:''})); }
function totalCompra(){ const g=n=>{ const e=$('#cm_'+n); return e?e.value:''; };
  const items=leerItemsCompra(); const c=calcCompra({items,ivaPct:num(g('iva'))||0,ivaRec:$('#cm_ivarec').checked,flete:num(g('flete'))||0,otros:num(g('otros'))||0});
  items.forEach((it,i)=>{ const e=$('#cs_'+i); if(e) e.textContent=money2(it.cant*it.costo); });
  $('#ctot').innerHTML=`Neto <b>${money2(c.neto)}</b> &nbsp;·&nbsp; IVA <b>${money2(c.iva)}</b> &nbsp;·&nbsp; Total a pagar <b>${money2(c.total)}</b> &nbsp;·&nbsp; Costo real <b>${money2(c.costoReal)}</b>`; }
LIVE['cmp-row']=el=>{ const i=+el.dataset.i,k=el.dataset.k; CD.items[i][k]=el.value;
  if(k==='pid'){ const p=prod(+el.value); const vid=+$('#cm_prov').value; if(p){ const cat=S.catalogo.find(c=>c.productoId===p.id&&c.proveedorId===vid); CD.items[i].costo=fnum(cat?cat.precio:p.costo); } pintarFilasCompra(); } else totalCompra(); };
LIVE['cmp-top']=()=>totalCompra();
ACT['cmp-add']=()=>{ CD.items.push({pid:'',cant:'',costo:'',vence:''}); pintarFilasCompra(); };
ACT['cmp-del']=el=>{ CD.items.splice(+el.dataset.i,1); if(!CD.items.length) CD.items.push({pid:'',cant:'',costo:'',vence:''}); pintarFilasCompra(); };
ACT['compra-nueva']=()=>modalCompra(null);
function modalCompra(pre){
  if(!S.productos.length||!S.proveedores.length){ toast('Primero cargá al menos un proveedor y un producto.',true); return; }
  const P=pre||{}; CD={reemplaza:P.reemplaza||null,items:(P.items&&P.items.length)?P.items.map(i=>({pid:i.pid,cant:fnum(i.cant),costo:fnum(i.costo),vence:i.vence||''})):[{pid:'',cant:'',costo:'',vence:''}]};
  const L=(n,l,inner)=>`<label class="field">${l}${inner}</label>`; const inp=(n,v,ph)=>`<input id="cm_${n}" data-live="cmp-top" value="${esc(v)}" inputmode="decimal" ${ph?`placeholder="${ph}"`:''}>`;
  abrir(P.reemplaza?'Corregir compra #'+P.reemplaza:'Nueva compra',`${P.reemplaza?`<div class="al info mb12"><div class="grow">Corregí lo que haga falta y guardá. La compra #${P.reemplaza} queda anulada y se registra esta en su lugar, con el stock y los costos recalculados.</div></div>`:''}<div class="frm" style="grid-template-columns:repeat(auto-fit,minmax(170px,1fr))">${L('fecha','Fecha',`<input type="date" id="cm_fecha" value="${esc(P.fecha||hoy())}">`)}${L('prov','Proveedor',`<select id="cm_prov" data-live="cmp-top">${opts(selProveedores(),P.proveedorId)}</select>`)}${L('pago','Pago',`<select id="cm_pago">${opts(['Efectivo','Transferencia','Pendiente'],P.pago||'Efectivo')}</select>`)}${L('iva','IVA %',inp('iva',fnum(P.ivaPct!=null?P.ivaPct:S.config.iva)))}${L('flete','Flete ($)',inp('flete',P.flete?fnum(P.flete):'','0'))}${L('otros','Otros gastos ($)',inp('otros',P.otros?fnum(P.otros):'','0'))}</div>
  <label class="field inline" style="margin:10px 0"><input type="checkbox" id="cm_ivarec" ${P.ivaRec===false?'':'checked'} data-live="cmp-top"> El IVA es recuperable (crédito fiscal): no suma al costo real</label>
  <div class="tw"><table><thead><tr><th>Producto</th><th>Cantidad</th><th>Costo unit. sin IVA</th>${S.config.venc?'<th>Vence</th>':''}<th class="n">Subtotal</th><th></th></tr></thead><tbody id="cmprows"></tbody></table></div>
  <div class="bar mt8"><button class="btn sm" data-act="cmp-add">+ Agregar producto</button></div><div id="ctot" style="margin-top:12px;font-size:15px"></div><label class="field mt12">Observaciones<input id="cm_obs" value="${esc(P.obs||'')}"></label><div id="err" class="sm dn mt8" role="alert"></div>
  <p class="sm muted">Al guardar se suma el stock, se registran los precios del proveedor y el costo de cada producto se actualiza con el costo real (el flete y los otros gastos se reparten entre los productos).</p>`,
  {wide:true,noFocus:true,foot:`<button class="btn" data-act="cerrar">Cancelar</button><button class="btn pri" id="cmpok">${P.reemplaza?'Guardar corrección':'Guardar compra'}</button>`});
  pintarFilasCompra(); $('#cmpok').onclick=guardarCompraForm; }
function guardarCompraForm(){ try{ const g=n=>$('#cm_'+n).value; const vid=+g('prov'); if(!vid) throw new Error('Elegí el proveedor.');
    const items=leerItemsCompra(); const vistos=new Set(); items.forEach((it,i)=>{ if(!it.productoId) throw new Error('Fila '+(i+1)+': elegí el producto.'); if(it.cant<=0) throw new Error('Fila '+(i+1)+': la cantidad tiene que ser mayor a 0.'); if(vistos.has(it.productoId)) throw new Error('Fila '+(i+1)+': el producto está repetido. Sumá las cantidades en una sola fila.'); vistos.add(it.productoId); });
    const orig=CD.reemplaza?S.compras.find(x=>x.id===CD.reemplaza):null; if(CD.reemplaza&&(!orig||orig.estado==='Anulada')) throw new Error('La compra #'+CD.reemplaza+' ya no se puede corregir: está anulada.');
    if(orig) anularCompra(orig.id); // primero sale lo de la compra vieja y después entra la corregida
    const id=crearCompra({fecha:g('fecha')||hoy(),proveedorId:vid,pago:g('pago'),ivaPct:num(g('iva'))||0,ivaRec:$('#cm_ivarec').checked,flete:num(g('flete'))||0,otros:num(g('otros'))||0,items,obs:g('obs')});
    if(orig){ const nueva=S.compras.find(x=>x.id===id); orig.corregidaPor=id; nueva.corrige=orig.id; if(orig.fechaPago&&nueva.pago===orig.pago) nueva.fechaPago=orig.fechaPago; guardar(); }
    cerrar(); indexar(); UI.compTab='lista'; if(UI.vista!=='compras') ir('compras'); else render(); toast(orig?'Compra #'+orig.id+' corregida: ahora es la #'+id:'Compra #'+id+' registrada'); }catch(e){ $('#err').textContent=e.message; } }

/* pedido sugerido */
function gruposPedido(){ const g={}; S.productos.filter(p=>p.activo&&stockDe(p.id)<=p.minimo).forEach(p=>{ const q=sugerido(p); if(q<=0) return; const v=mejorProveedor(p.id)||0; (g[v]=g[v]||[]).push({p,q}); }); return g; }
function pedidoHtml(){ const g=gruposPedido(); const ks=Object.keys(g); if(!ks.length) return vacioHtml('No hay nada para reponer. Todos los productos están por encima del stock mínimo.');
  return `<p class="sm muted mt0">Productos en o bajo el mínimo, agrupados por el proveedor con el mejor precio. La cantidad sugerida cubre el doble del mínimo o unos 14 días de venta, lo que sea mayor. Podés editarla.</p>`+ks.map(k=>{ const v=IDX.prov[k];
    return `<div class="card mb12" id="pg_${k}"><h2>${v?dot(v.color)+esc(v.nombre):'Sin proveedor asignado'} ${v&&v.telefono?`<span class="sm muted" style="font-weight:400">· ${esc(v.telefono)}</span>`:''}</h2><div class="tw"><table><thead><tr><th>Producto</th><th class="n">Stock</th><th class="n">Mínimo</th><th class="n" style="width:130px">Pedir</th><th class="n">Precio ref.</th></tr></thead><tbody>${g[k].map(({p,q})=>`<tr><td>${esc(p.nombre)}</td><td class="n ${stockDe(p.id)<=0?'dn b':''}">${qtyTxt(p,stockDe(p.id))}</td><td class="n">${qtyTxt(p,p.minimo)}</td><td class="n"><input data-live="ped" data-g="${k}" data-id="${p.id}" value="${fnum(q)}" inputmode="decimal" style="text-align:right;width:90px"></td><td class="n">${money2(precioReferencia(p.id)||p.costo)}${p.unidad==='kg'?'/kg':''}</td></tr>`).join('')}</tbody></table></div>
      <div class="bar mt12"><button class="btn" data-act="ped-copiar" data-g="${k}">Copiar pedido</button>${v&&v.telefono?`<a class="btn" id="pw_${k}" target="_blank" rel="noopener" href="${wa(v.telefono,pedidoTxt(k))}">Enviar por WhatsApp</a>`:''}${v?`<button class="btn pri" data-act="ped-compra" data-g="${k}">Registrar compra</button>`:''}</div></div>`; }).join(''); }
function pedidoItems(k){ return [...document.querySelectorAll(`#pg_${k} input[data-live="ped"]`)].map(i=>{ const p=prod(+i.dataset.id); return {p,q:numCant(p,i.value)||0}; }).filter(x=>x.q>0); }
function pedidoTxt(k){ const v=IDX.prov[k]; const g=gruposPedido()[k]||[]; const its=document.querySelector('#pg_'+k)?pedidoItems(k):g.map(x=>({p:x.p,q:x.q}));
  return 'Hola'+(v&&v.contacto?' '+v.contacto:'')+', te paso el pedido de '+S.config.nombre+':\n'+its.map(x=>'• '+x.p.nombre+': '+(x.p.unidad==='kg'?fmt(x.q,2).replace(/,00$/,'')+' kg':fmt(x.q,0)+' u')).join('\n')+'\nGracias!'; }
LIVE.ped=el=>{ const k=el.dataset.g; const a=$('#pw_'+k); const v=IDX.prov[k]; if(a&&v) a.href=wa(v.telefono,pedidoTxt(k)); };
ACT['ped-copiar']=el=>copiar(pedidoTxt(el.dataset.g),'Pedido copiado');
ACT['ped-compra']=el=>{ const k=+el.dataset.g; modalCompra({proveedorId:k,items:pedidoItems(k).map(x=>({pid:x.p.id,cant:x.q,costo:(S.catalogo.find(c=>c.productoId===x.p.id&&c.proveedorId===k)||{precio:x.p.costo}).precio}))}); };

/* ================= PROVEEDORES ================= */
VIEWS.proveedores=function(){ const t=tabs([['prov','Proveedores'],['precios','Comparador de precios']],UI.provTab,'tab-prov'); const f=UI.f.pre;
  return `${encab('Proveedores','',`<button class="btn pri" data-act="prov-nuevo">Nuevo proveedor</button><button class="btn" data-act="precio-asignar">Asignar producto</button>`)}${t}${UI.provTab==='precios'?`<div class="filters"><label class="field">Buscar<span class="srch">${SVG(LUPA_D)}<input data-bind="f.pre.q" value="${esc(f.q)}" placeholder="Producto o proveedor"></span></label><label class="field">Ver<select data-bind="f.pre.ver">${opts([{v:'',t:'Todos los precios'},{v:'viejo',t:'Solo los desactualizados'},{v:'mejor',t:'Solo los mejores precios'}],f.ver)}</select></label></div>`:''}<div id="res"></div>`; };
ACT['tab-prov']=el=>{ UI.provTab=el.dataset.t; render(); };
FILL.proveedores=function(){ const r=$('#res'); if(!r) return;
  if(UI.provTab==='precios'){ const f=UI.f.pre,q=f.q.trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,''); const mejor={}; S.catalogo.forEach(c=>{ if(mejor[c.productoId]==null||c.precio<mejor[c.productoId]) mejor[c.productoId]=c.precio; });
    const l=S.catalogo.map(c=>({c,p:prod(c.productoId),d:difDias(hoy(),c.fecha),m:mejor[c.productoId]})).filter(x=>x.p&&(!q||x.p.nombre.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').includes(q)||provNom(x.c.proveedorId).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').includes(q))&&(f.ver!=='viejo'||x.d>S.config.diasPrecio)&&(f.ver!=='mejor'||Math.abs(x.c.precio-x.m)<0.005)).sort((a,b)=>a.p.nombre.localeCompare(b.p.nombre));
    r.innerHTML=l.length?`<div class="tw"><table><thead><tr><th>Producto</th><th>Proveedor</th><th class="n">Precio</th><th>Actualizado</th><th>Comparación</th></tr></thead><tbody>${l.map(x=>`<tr class="click" data-act="precio-edit" data-id="${x.c.id}"><td><b>${esc(x.p.nombre)}</b></td><td>${dot((IDX.prov[x.c.proveedorId]||{}).color)}${esc(provNom(x.c.proveedorId))}</td><td class="n b">${money2(x.c.precio)}</td><td>${fechaTxt(x.c.fecha)} ${x.d>S.config.diasPrecio?pill('warn','hace '+x.d+' d'):''}</td><td>${Math.abs(x.c.precio-x.m)<0.005?pill('good','Mejor precio'):pill('mute','+'+fmt((x.c.precio-x.m)/x.m*100,1)+'% vs. el mejor')}</td></tr>`).join('')}</tbody></table></div>`:vacioHtml('No hay precios cargados todavía. Se cargan solos al registrar compras o con «Asignar producto».'); return; }
  const l=S.proveedores.slice().sort((a,b)=>a.nombre.localeCompare(b.nombre));
  r.innerHTML=l.length?`<div class="provs">${l.map(v=>{ const cs=S.compras.filter(c=>c.proveedorId===v.id&&c.estado!=='Anulada'); const tot=cs.reduce((a,c)=>a+c.total,0), pend=cs.filter(c=>c.pago==='Pendiente').reduce((a,c)=>a+c.total,0); const uc=cs.map(c=>c.fecha).sort().pop();
    const np=S.catalogo.filter(c=>c.proveedorId===v.id).length; return `<div class="prv click" data-act="prov-ver" data-id="${v.id}" style="--pc:${esc(v.color||'#999')}"><div class="prh">${avatar(v.nombre)}<div class="fm"><b>${esc(v.nombre)}</b><span>${esc([v.contacto,v.telefono].filter(Boolean).join(' · ')||'Sin contacto cargado')}</span></div></div><dl><div><dt>Productos</dt><dd>${np}</dd></div><div><dt>Comprado</dt><dd>${money(tot)}</dd></div><div><dt>A pagar</dt><dd class="${pend>0?'dn':''}">${money(pend)}</dd></div></dl><div class="prf">${uc?'Última compra '+fechaTxt(uc):'Todavía sin compras'}</div></div>`; }).join('')}</div>`:vacioHtml('Todavía no cargaste proveedores.'); };
AFTER.proveedores=()=>FILL.proveedores();
const camposProv=[{n:'nombre',l:'Proveedor',t:'text',req:true,full:true},{n:'contacto',l:'Persona de contacto',t:'text'},{n:'telefono',l:'Teléfono / WhatsApp',t:'text',ph:'Con código de área'},{n:'email',mas:1,l:'Email',t:'text'},{n:'direccion',mas:1,l:'Dirección',t:'text'},{n:'color',l:'Color de sus productos',t:'color'},{n:'notas',mas:1,l:'Notas',t:'area',full:true}];
ACT['prov-nuevo']=()=>provForm(null);
function provForm(v){ formModal(v?'Editar proveedor':'Nuevo proveedor',camposProv,v||{color:['#1d7a4e','#b4373d','#1f4fd8','#9a5a05','#7a3db5','#0f7c86'][S.proveedores.length%6]},d=>{
  if(S.proveedores.some(x=>x.nombre.toLowerCase()===d.nombre.toLowerCase()&&(!v||x.id!==v.id))) throw new Error('Ya existe un proveedor con ese nombre.');
  if(v) Object.assign(v,d); else S.proveedores.push(Object.assign({id:sig('V')},d)); indexar(); guardar(); cerrar(); refrescar(); toast('Proveedor guardado'); }); }
ACT['prov-ver']=el=>{ const v=IDX.prov[+el.dataset.id]; const cat=S.catalogo.filter(c=>c.proveedorId===v.id&&prod(c.productoId)); const mejor={}; S.catalogo.forEach(c=>{ if(mejor[c.productoId]==null||c.precio<mejor[c.productoId]) mejor[c.productoId]=c.precio; });
  const link=wa(v.telefono,'Hola '+(v.contacto||'')+'!');
  abrir(v.nombre,`<p class="mt0">${esc(v.contacto||'')} ${v.telefono?'· '+esc(v.telefono):''} ${v.email?'· '+esc(v.email):''}<br><span class="muted">${esc(v.direccion||'')}</span></p>${v.notas?`<p class="sm muted">${esc(v.notas)}</p>`:''}
  <h2 style="font-size:20px">Catálogo de precios</h2>${cat.length?`<div class="tw"><table><thead><tr><th>Producto</th><th class="n">Precio</th><th>Actualizado</th><th>Comparación</th></tr></thead><tbody>${cat.map(c=>{ const p=prod(c.productoId); return `<tr class="click" data-act="precio-edit" data-id="${c.id}"><td>${esc(p.nombre)}</td><td class="n b">${money2(c.precio)}</td><td>${fechaTxt(c.fecha)}</td><td>${Math.abs(c.precio-mejor[c.productoId])<0.005?pill('good','Mejor precio'):pill('mute','+'+fmt((c.precio-mejor[c.productoId])/mejor[c.productoId]*100,1)+'%')}</td></tr>`; }).join('')}</tbody></table></div>`:vacioHtml('Todavía no tiene productos asignados.')}`,
  {wide:true,foot:`<button class="btn bad sm" data-act="prov-del" data-id="${v.id}">Eliminar</button><span class="grow"></span>${link?`<a class="btn" href="${link}" target="_blank" rel="noopener">WhatsApp</a>`:''}<button class="btn" data-act="prov-edit" data-id="${v.id}">Editar</button><button class="btn" data-act="precio-asignar" data-v="${v.id}">Asignar producto</button><button class="btn pri" data-act="cerrar">Cerrar</button>`}); };
ACT['prov-edit']=el=>provForm(IDX.prov[+el.dataset.id]);
ACT['prov-del']=el=>{ const v=IDX.prov[+el.dataset.id]; if(S.compras.some(c=>c.proveedorId===v.id)){ toast('«'+v.nombre+'» tiene compras registradas y no se puede borrar para no perder el historial.',true); return; }
  confirmar('¿Eliminar al proveedor «'+esc(v.nombre)+'» y sus precios?',()=>{ S.proveedores=S.proveedores.filter(x=>x.id!==v.id); S.catalogo=S.catalogo.filter(x=>x.proveedorId!==v.id); S.historial=S.historial.filter(x=>x.proveedorId!==v.id); indexar(); guardar(); refrescar(); toast('Proveedor eliminado'); },'Eliminar'); };
ACT['precio-asignar']=el=>{ if(!S.productos.length||!S.proveedores.length){ toast('Primero cargá al menos un producto y un proveedor.',true); return; }
  formModal('Asignar producto a un proveedor',[{n:'pid',l:'Producto',t:'select',o:selProductos(true),req:true,full:true},{n:'vid',l:'Proveedor',t:'select',o:selProveedores(),full:true},{n:'precio',l:'Precio de compra sin IVA ($)',t:'num',req:true,min:0},{n:'fecha',l:'Fecha del precio',t:'date'}],{vid:el.dataset.v||'',fecha:hoy()},d=>{
    if(!d.pid) throw new Error('Elegí el producto.'); registrarPrecio(+d.pid,+d.vid,d.precio,d.fecha||hoy(),'Manual'); guardar(); cerrar(); refrescar(); toast('Precio registrado'); }); };
ACT['precio-edit']=el=>{ const c=S.catalogo.find(x=>x.id===+el.dataset.id); const p=prod(c.productoId);
  formModal('Actualizar precio · '+p.nombre,[{n:'precio',l:'Precio de compra sin IVA ($) · '+provNom(c.proveedorId),t:'num',req:true,min:0,full:true},{n:'fecha',l:'Fecha del precio',t:'date'}],{precio:c.precio,fecha:hoy()},d=>{ registrarPrecio(c.productoId,c.proveedorId,d.precio,d.fecha||hoy(),'Manual'); guardar(); cerrar(); refrescar(); toast('Precio actualizado'); },{foot:`<button class="btn sm" type="button" data-act="prod-hist" data-id="${p.id}">Ver historial</button><span class="grow"></span>`}); };

/* ================= CLIENTES ================= */
VIEWS.clientes=function(){ const f=UI.f.cli;
  return `${encab('Clientes','',`<button class="btn" data-act="cobro-comp">Cargar comprobante de pago</button><button class="btn pri" data-act="cli-nuevo">Nuevo cliente</button>`)}<div class="filters"><label class="field">Buscar<span class="srch">${SVG(LUPA_D)}<input data-bind="f.cli.q" value="${esc(f.q)}" placeholder="Nombre o teléfono"></span></label><label class="field">Ver<select data-bind="f.cli.ver">${opts([{v:'activos',t:'Activos'},{v:'archivados',t:'Archivados'},{v:'todos',t:'Todos'}],f.ver)}</select></label></div><div id="res"></div>`; };
FILL.clientes=function(){ const r=$('#res'); if(!r) return; const q=UI.f.cli.q.trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'');
  const ver=UI.f.cli.ver||'activos'; const l=S.clientes.filter(c=>(ver==='todos'||(ver==='archivados')===!!c.archivado)&&(!q||c.nombre.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').includes(q)||(c.telefono||'').includes(q))).sort((a,b)=>saldoCliente(b.id)-saldoCliente(a.id)||a.nombre.localeCompare(b.nombre));
  const deb=l.filter(c=>saldoCliente(c.id)>0.004), tCob=deb.reduce((a,c)=>a+saldoCliente(c.id),0), fav=l.reduce((a,c)=>a+Math.max(0,-saldoCliente(c.id)),0);
  const nAct=S.clientes.filter(c=>!c.archivado).length, nArch=S.clientes.length-nAct;
  r.innerHTML=franja('cli-filtro',ver,[{v:'activos',k:'Clientes activos',n:nAct},{v:'archivados',k:'Archivados',n:nArch},{v:'todos',k:'Total a cobrar',n:money(tCob),cls:tCob>0?'bad':''}])+(l.length?`<div class="filas">${l.map(c=>{ const vs=S.ventas.filter(v=>v.clienteId===c.id&&v.estado!=='Anulada'); const s=saldoCliente(c.id); const uc=vs.map(v=>v.fecha).sort().pop();
    return `<div class="fila click ${c.archivado?'off':''}" data-act="cli-ver" data-id="${c.id}">${avatar(c.nombre)}<div class="fm"><b>${esc(c.nombre)}${c.archivado?' '+pill('mute','Archivado'):''}</b><span>${[esc(c.telefono||''),vs.length?vs.length+' compra'+(vs.length===1?'':'s')+' · '+money(vs.reduce((a,v)=>a+v.total,0)):'Sin compras',uc?'última '+fechaTxt(uc):''].filter(Boolean).join(' · ')}</span></div><div class="fn">${s>0.004?`<b class="dn">${money(s)}</b><span>debe</span>`:s<-0.004?`<b class="up">${money(-s)}</b><span>a favor</span>`:'<span>al día</span>'}</div></div>`; }).join('')}</div>`:vacioHtml(S.clientes.length?(ver==='archivados'?'No hay clientes archivados.':'No hay clientes con esa búsqueda.'):'Todavía no cargaste clientes. Los clientes sirven para vender en cuenta corriente y ver quién compra más.')); };
AFTER.clientes=()=>FILL.clientes();
const camposCli=[{n:'nombre',l:'Nombre',t:'text',req:true,full:true},{n:'telefono',l:'Teléfono / WhatsApp',t:'text',ph:'Con código de área'},{n:'cuit',mas:1,l:'CUIT / CUIL',t:'text',ph:'Para reconocer sus transferencias'},{n:'direccion',mas:1,l:'Dirección',t:'text'},{n:'cierre',mas:1,l:'Día de cierre de la cuenta',t:'num',min:0,ph:'Vacío = fin de mes',hint:'Ej. 15: cada período va del 16 de un mes al 15 del siguiente.'},{n:'notas',mas:1,l:'Notas',t:'area',full:true}];
ACT['cli-filtro']=el=>{ UI.f.cli.ver=el.dataset.v; render(); };
ACT['cli-nuevo']=()=>cliForm(null);
function cliForm(c){ formModal(c?'Editar cliente':'Nuevo cliente',camposCli,c?Object.assign({},c,{cierre:c.cierre||''}):{},d=>{ if(d.cierre>31||d.cierre%1) throw new Error('El día de cierre tiene que ser un número del 1 al 31.'); if(c) Object.assign(c,d); else S.clientes.push(Object.assign({id:sig('Q'),creado:hoy()},d)); indexar(); guardar(); cerrar(); refrescar(); toast('Cliente guardado'); }); }
ACT['cli-edit']=el=>cliForm(IDX.cli[+el.dataset.id]);
/* ficha del cliente con la cuenta corriente como planilla (debe / haber / saldo) por período de cierre */
UI.cc={id:null,per:'0'};
const rangoPer=(c,per)=>per==='todo'?{desde:'',hasta:''}:cicloCC(c,+per);
function opcionesPer(c){ const o=[], a=hoy().slice(0,4); for(let k=0;k<12;k++){ const r=cicloCC(c,k); o.push({v:String(k),t:(k===0?'Actual · ':'')+fechaCorta(r.desde)+' al '+fechaCorta(r.hasta)+(r.hasta.slice(0,4)!==a?'/'+r.hasta.slice(2,4):'')}); } o.push({v:'todo',t:'Toda la cuenta'}); return o; }
function resumenCCTxt(c,per){ const r=rangoPer(c,per),R=resumenCC(c.id,r.desde,r.hasta);
  const L=[S.config.nombre+' · Resumen de cuenta','Cliente: '+c.nombre,per==='todo'?'Toda la cuenta':'Período del '+fechaTxt(r.desde)+' al '+fechaTxt(r.hasta),''];
  if(per!=='todo') L.push('Saldo anterior: '+money2(R.anterior)); R.L.forEach(m=>L.push(fechaCorta(m.fecha)+' '+m.concepto+': '+(m.debe?'+ '+money2(m.debe):'- '+money2(m.haber))));
  L.push('','Compras y cargos: '+money2(R.debe),'Pagos y descuentos: '+money2(R.haber),'SALDO'+(per==='todo'?'':' AL '+fechaTxt(r.hasta))+': '+money2(R.saldo),'','¡Gracias!'); return L.join('\n'); }
function planillaCC(c,per,sinWa){ const r=rangoPer(c,per),R=resumenCC(c.id,r.desde,r.hasta); const link=wa(c.telefono,resumenCCTxt(c,per));
  const fila=m=>`<tr ${m.tipo==='venta'?`class="click" data-act="venta-ver" data-id="${m.ref}" title="Ver la venta"`:''}><td>${fechaTxt(m.fecha)}</td><td>${esc(m.concepto)}${m.comprobante?` <button class="btn sm ghost" data-act="adj-ver" data-id="${esc(m.comprobante.id)}" title="Ver comprobante" aria-label="Ver comprobante">${CLIP}</button>`:''}${m.tipo==='ajuste'?` <button class="btn sm ghost" data-act="cc-aj-del" data-id="${m.ref}" data-cli="${c.id}" title="Borrar movimiento" aria-label="Borrar movimiento">✕</button>`:m.tipo==='cobro'?` <button class="btn sm ghost" data-act="cc-cobro-del" data-id="${m.ref}" data-cli="${c.id}" title="Borrar este pago" aria-label="Borrar este pago">✕</button>`:''}</td><td class="n">${m.debe?money2(m.debe):''}</td><td class="n up">${m.haber?money2(m.haber):''}</td><td class="n b ${m.saldo>0.004?'dn':''}">${money2(m.saldo)}</td></tr>`;
  const ini=per==='todo'?'':`<tr class="muted"><td>${fechaTxt(addDias(r.desde,-1))}</td><td><i>Saldo anterior</i></td><td></td><td></td><td class="n b">${money2(R.anterior)}</td></tr>`;
  return `<div class="ccsum"><div><span>Saldo anterior</span><b>${money2(R.anterior)}</b></div><div><span>+ Compras y cargos</span><b>${money2(R.debe)}</b></div><div><span>− Pagos y descuentos</span><b class="up">${money2(R.haber)}</b></div><div class="tot"><span>Saldo${per==='todo'?'':' al '+fechaCorta(r.hasta)}</span><b class="${R.saldo>0.004?'dn':''}">${money2(R.saldo)}</b></div></div>${link&&!sinWa?`<div style="text-align:right;margin-bottom:10px"><a class="btn sm" href="${link}" target="_blank" rel="noopener">Enviar resumen por WhatsApp</a></div>`:''}
  ${R.L.length?`<div class="tw"><table class="cct"><thead><tr><th>Fecha</th><th>Concepto</th><th class="n">Debe</th><th class="n">Haber</th><th class="n">Saldo</th></tr></thead><tbody>${ini}${R.L.map(fila).join('')}</tbody></table></div>`
   :`<div class="ccvac"><b>Sin movimientos ${per==='todo'?'en la cuenta':'del '+fechaCorta(r.desde)+' al '+fechaCorta(r.hasta)}</b><span>${per==='todo'?'Este cliente todavía no compró a cuenta ni hizo pagos.':Math.abs(R.saldo)>0.004?'El saldo de '+money2(R.saldo)+' viene de períodos anteriores.':'No tuvo compras ni pagos en este período.'}</span>${per==='todo'?'':`<div class="bar"><button class="btn sm" data-act="cc-perv" data-v="${(+per||0)+1}">Ver período anterior</button><button class="btn sm" data-act="cc-perv" data-v="todo">Ver toda la cuenta</button></div>`}</div>`}`; }
function fichaCliente(id){ const c=IDX.cli[id]; if(!c) return; if(UI.cc.id!==id) UI.cc={id,per:'0'}; const s=saldoCliente(id);
  const vs=S.ventas.filter(v=>v.clienteId===id).sort((a,b)=>b.id-a.id).slice(0,8);
  abrir(c.nombre,`<div class="kpis mb12"><div class="kpi ${s>0?'bad':'good'}"><div class="k">${s<-0.004?'Saldo a favor del cliente':'Saldo a cobrar'}</div><div class="v">${money(Math.abs(s))}</div></div><div class="kpi"><div class="k">Contacto</div><div class="v" style="font-size:16px">${esc(c.telefono||'—')}</div><div class="d">${esc(c.direccion||'')}${c.cuit?(c.direccion?' · ':'')+'CUIT '+esc(c.cuit):''}</div></div><div class="kpi"><div class="k">Cierre de cuenta</div><div class="v" style="font-size:16px">${c.cierre?'Día '+c.cierre:'Fin de mes'}</div><div class="d">Se cambia en «Editar»</div></div></div>
  <div class="cchead"><h2 style="font-size:20px;margin:0">Cuenta corriente</h2><div class="bar"><select data-chg="cc-per" aria-label="Período">${opts(opcionesPer(c),UI.cc.per)}</select><button class="btn sm" data-act="cc-aj" data-id="${id}">Cargo o descuento</button><button class="btn sm" data-act="cc-csv" data-id="${id}">Exportar a Excel</button></div></div>
  <div id="ccbox">${planillaCC(c,UI.cc.per)}</div>${archivosHtml(id)}
  <h2 style="font-size:20px;margin-top:18px">Últimas compras (todos los medios)</h2>${vs.length?`<div class="tw"><table><tbody>${vs.map(v=>`<tr class="click ${v.estado==='Anulada'?'off':''}" data-act="venta-ver" data-id="${v.id}"><td>${fechaCorta(v.fecha)}</td><td>#${v.id}</td><td>${esc(v.medio)}</td><td class="n">${money(v.total)}</td></tr>`).join('')}</tbody></table></div>`:vacioHtml('Sin compras.')}`,
  {wide:true,noFocus:true,foot:`${c.archivado?`<button class="btn sm" data-act="cli-desarch" data-id="${id}">Desarchivar</button>`:`<button class="btn sm bad" data-act="cli-del" data-id="${id}">${tieneHistorial(id)?'Archivar':'Eliminar'}</button>`}<span class="grow"></span><button class="btn" data-act="cli-edit" data-id="${id}">Editar</button><button class="btn pri" data-act="cli-cobro" data-id="${id}">Registrar cobro</button><button class="btn" data-act="cerrar">Cerrar</button>`}); }
ACT['cli-ver']=el=>fichaCliente(+el.dataset.id);
// un cliente con ventas, pagos o archivos no se borra: se archiva para no perder su historial
const tieneHistorial=id=>S.ventas.some(v=>v.clienteId===id)||S.cobros.some(x=>x.clienteId===id)||(S.ajustesCC||[]).some(x=>x.clienteId===id)||(S.archivos||[]).some(x=>x.clienteId===id);
ACT['cli-del']=el=>{ const id=+el.dataset.id, c=IDX.cli[id]; if(!c) return;
  if(!tieneHistorial(id)) return confirmar(`¿Eliminar a <b>${esc(c.nombre)}</b>? No tiene ventas ni pagos registrados.`,()=>{ S.clientes=S.clientes.filter(x=>x.id!==id); if(String(UI.cart.clienteId)===String(id)) UI.cart.clienteId=''; if(UI.cc.id===id) UI.cc={id:null,per:'0'}; indexar(); guardar(); cerrar(); refrescar(); toast('Cliente eliminado'); },'Eliminar');
  const s=saldoCliente(id);
  confirmar(`¿Archivar a <b>${esc(c.nombre)}</b>? Deja de aparecer en la lista y al vender, pero sus ventas y su cuenta corriente se conservan. Lo podés ver eligiendo «Archivados» en Clientes.${Math.abs(s)>0.004?`<div class="al warn mt12"><div class="grow">${s>0?'<b>Todavía debe '+money2(s)+'.</b> Va a seguir apareciendo en Cuenta corriente hasta que salde la deuda.':'<b>Tiene '+money2(-s)+' a favor.</b>'}</div></div>`:''}`,()=>{ c.archivado=true; if(String(UI.cart.clienteId)===String(id)) UI.cart.clienteId=''; guardar(); cerrar(); refrescar(); toast('Cliente archivado'); },'Archivar'); };
