const enCCVentas=()=>UI.vista==='ventas'&&UI.ventasTab==='cc';
function volverCC(id){ if(enCCVentas()){ cerrar(); UI.cc.id=id; indexar(); FILL.ventas(); } else fichaCliente(id); }
function ccVentasHtml(){ const f=UI.f.ccv, q=f.q.trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'');
  const filas=S.clientes.map(c=>{ const L=movsCC(c.id); return {c,s:saldoCliente(c.id),n:L.length,ult:L.length?L[L.length-1].fecha:null}; })
    .filter(x=>(f.ver==='todos'||(f.ver==='saldo'?Math.abs(x.s)>0.004:x.n>0&&!x.c.archivado))&&(!q||x.c.nombre.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').includes(q)||(x.c.telefono||'').includes(q)||String(x.c.cuit||'').replace(/\D/g,'').includes(q.replace(/\D/g,'')||'§')))
    .sort((a,b)=>b.s-a.s||a.c.nombre.localeCompare(b.c.nombre));
  const total=r2(S.clientes.reduce((a,c)=>a+Math.max(0,saldoCliente(c.id)),0));
  if(!filas.some(x=>x.c.id===UI.cc.id)) UI.cc={id:filas.length?filas[0].c.id:null,per:'0'};
  const lista=filas.length?`<div class="ccl"><table><tbody>${filas.map(x=>`<tr class="click ${x.c.id===UI.cc.id?'sel':''}" data-act="ccv-sel" data-id="${x.c.id}"><td><b>${esc(x.c.nombre)}</b><div class="sm muted">${x.c.archivado?'Archivado · ':''}${x.c.cierre?'Cierra el '+x.c.cierre:'Cierra fin de mes'}${x.ult?' · últ. mov. '+fechaCorta(x.ult):''}</div></td><td class="n b ${x.s>0.004?'dn':x.s<-0.004?'up':''}">${x.s<-0.004?'<span class="sm" style="display:block;font-weight:600">a favor</span>'+money(-x.s):money(x.s)}</td></tr>`).join('')}</tbody></table></div>`
    :vacioHtml(f.ver==='saldo'?'Ningún cliente debe plata. Elegí «Todos» para ver el resto.':'No hay clientes con esa búsqueda.');
  const c=UI.cc.id?IDX.cli[UI.cc.id]:null, s=c?saldoCliente(c.id):0;
  const det=c?`<div class="card"><div class="cchead"><div><h2 style="font-size:20px;margin:0">${esc(c.nombre)}</h2><div class="sm muted">${esc(c.telefono||'Sin teléfono')}${c.cuit?' · CUIT '+esc(c.cuit):''} · ${s<-0.004?'<b class="up">Saldo a favor '+money2(-s)+'</b>':'Debe <b class="'+(s>0.004?'dn':'')+'">'+money2(s)+'</b>'}</div></div>
      <label class="ccper"><span>Período</span><select data-chg="cc-per">${opts(opcionesPer(c),UI.cc.per)}</select></label></div>
    <div class="ccacc"><button class="btn sm" data-act="cli-cobro" data-id="${c.id}">${SVG('<rect x="2.5" y="6" width="19" height="12" rx="2"/><circle cx="12" cy="12" r="2.6"/>')}Registrar cobro</button><button class="btn sm" data-act="cc-aj" data-id="${c.id}">${SVG('<path d="M12 5v14M5 12h14"/>')}Cargo o descuento</button><button class="btn sm" data-act="cli-ver" data-id="${c.id}">${SVG('<circle cx="12" cy="8" r="3.5"/><path d="M5 20a7 7 0 0 1 14 0"/>')}Ver ficha</button>${c.telefono?`<button class="btn sm" data-act="cc-wa" data-id="${c.id}">${SVG('<path d="M4 20l1.3-3.9A8 8 0 1 1 8 19z"/>')}Enviar resumen por WhatsApp</button>`:''}<button class="btn sm" data-act="cc-csv" data-id="${c.id}">${SVG('<path d="M12 4v11M7.5 10.5 12 15l4.5-4.5M5 20h14"/>')}Exportar Excel</button></div>
    <div id="ccbox">${planillaCC(c,UI.cc.per,true)}</div>${archivosHtml(c.id)}</div>`:'';
  const deben=S.clientes.filter(x=>saldoCliente(x.id)>0.004).length;
  const st=$('#ccstrip'); if(st) st.innerHTML=`<div class="ccstrip"><span>Total a cobrar <b class="${total>0?'dn':''}">${money(total)}</b></span><span class="dot"></span><span><b>${deben}</b> cliente${deben===1?' debe':'s deben'}</span></div>`;
  const d=$('#ccdet'); if(d) d.innerHTML=det;
  return lista; }
ACT['cc-wa']=el=>{ const c=IDX.cli[+el.dataset.id]; const l=c&&wa(c.telefono,resumenCCTxt(c,UI.cc.per)); if(l) window.open(l,'_blank','noopener'); };
document.addEventListener('click',e=>{ document.querySelectorAll('details.mnu[open]').forEach(m=>{ if(!m.contains(e.target)||e.target.closest('.mnu div button')) m.open=false; }); });
ACT['cc-perv']=el=>{ const v=el.dataset.v, b=el.closest('#ccbox'), sel=b&&b.parentElement.querySelector('[data-chg="cc-per"]'); UI.cc.per=v; if(sel) sel.value=v; const c=IDX.cli[UI.cc.id]; if(c&&b) b.innerHTML=planillaCC(c,v,!!el.closest('#ccdet')); };
ACT['ccv-sel']=el=>{ const id=+el.dataset.id; if(UI.cc.id!==id) UI.cc={id,per:'0'}; FILL.ventas(); };
CHG['cc-per']=el=>{ UI.cc.per=el.value; const c=IDX.cli[UI.cc.id]; const b=$('#ccbox'); if(c&&b) b.innerHTML=planillaCC(c,el.value,enCCVentas()); };
ACT['cc-csv']=el=>{ const c=IDX.cli[+el.dataset.id]; const per=UI.cc.per, r=rangoPer(c,per), R=resumenCC(c.id,r.desde,r.hasta); const f=n=>String(n).replace('.',',');
  const rows=(per==='todo'?[]:[[addDias(r.desde,-1),'Saldo anterior','','',f(R.anterior)]]).concat(R.L.map(m=>[m.fecha,m.concepto,m.debe?f(m.debe):'',m.haber?f(m.haber):'',f(m.saldo)]));
  rows.push(['','Totales',f(R.debe),f(R.haber),f(R.saldo)]);
  descargar('cuenta_'+c.nombre.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/[^a-z0-9]+/g,'_')+'_'+(per==='todo'?'completa':r.desde+'_a_'+r.hasta)+'.csv',aCSV(['fecha','concepto','debe','haber','saldo'],rows)); };
ACT['cc-aj']=el=>{ const id=+el.dataset.id, c=IDX.cli[id];
  formModal('Cargo o descuento · '+c.nombre,[{n:'tipo',l:'Tipo',t:'select',full:true,o:[{v:'Cargo',t:'Cargo: suma a la deuda (saldo inicial, flete, etc.)'},{v:'Abono',t:'Descuento o nota de crédito: resta de la deuda'}]},{n:'monto',l:'Monto ($)',t:'num',req:true,min:0.01},{n:'fecha',l:'Fecha',t:'date'},{n:'concepto',l:'Concepto',t:'text',req:true,full:true,ph:'Ej. Saldo inicial, Bonificación, Devolución'}],{tipo:'Cargo',fecha:hoy()},d=>{
    if(d.tipo==='Abono'&&d.monto>saldoCliente(id)+0.005) throw new Error('El descuento supera el saldo ('+money2(saldoCliente(id))+').');
    S.ajustesCC.push({id:sig('J'),clienteId:id,tipo:d.tipo,monto:d.monto,fecha:d.fecha||hoy(),concepto:d.concepto}); guardar(); refrescar(); volverCC(id); toast('Movimiento agregado'); },{foot:enCCVentas()?'':`<button class="btn" type="button" data-act="cli-ver" data-id="${id}">Volver</button><span class="grow"></span>`}); };
ACT['cc-aj-del']=el=>{ const id=+el.dataset.id, cid=+el.dataset.cli; confirmar('¿Borrar este movimiento de la cuenta corriente?',()=>{ S.ajustesCC=S.ajustesCC.filter(a=>a.id!==id); guardar(); refrescar(); volverCC(cid); toast('Movimiento borrado'); },'Borrar'); };
ACT['cli-cobro']=el=>modalCobro(+el.dataset.id);
