ACT['cc-cobro-del']=el=>{ const id=+el.dataset.id, cid=+el.dataset.cli, x=S.cobros.find(z=>z.id===id); if(!x) return;
  const cerrada=x.medio==='Efectivo'&&S.cajas.some(k=>k.fecha===x.fecha);
  confirmar(`¿Borrar el pago de <b>${money2(x.monto)}</b> del ${fechaTxt(x.fecha)} (${esc(x.medio)})? La deuda de ${esc(cliNom(cid))} vuelve a subir ${money2(x.monto)}.${x.comprobante?' También se borra el comprobante adjunto.':''}${cerrada?'<br><br>La caja de ese día ya está cerrada: después revisá el cierre.':''}`,()=>{
    S.cobros=S.cobros.filter(z=>z.id!==id); guardar(); if(x.comprobante&&typeof adjBorrar==='function') adjBorrar(x.comprobante.id).catch(()=>{});
    refrescar(); volverCC(cid); toast('Pago borrado'); },'Borrar pago'); }; // en comprobantes.js: cobro con comprobante adjunto y lectura automática

/* ================= GASTOS ================= */
VIEWS.gastos=function(){ const f=UI.f.gas;
  return `${encab('Gastos','',`<button class="btn pri" data-act="gasto-nuevo">Nuevo gasto</button>`)}<div class="filters"><label class="field">Buscar<span class="srch">${SVG(LUPA_D)}<input data-bind="f.gas.q" value="${esc(f.q)}" placeholder="Concepto o categoría"></span></label><label class="field">Desde<input type="date" data-bind="f.gas.desde" value="${esc(f.desde)}"></label></div><div id="res"></div>`; };
FILL.gastos=function(){ const r=$('#res'); if(!r) return; const f=UI.f.gas,q=f.q.trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'');
  const l=S.gastos.filter(g=>(!f.desde||g.fecha>=f.desde)&&(!q||g.concepto.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').includes(q)||(g.categoria||'').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').includes(q))).sort((a,b)=>a.fecha<b.fecha?1:-1);
  const tot=l.reduce((a,g)=>a+g.monto+g.iva,0);
  const porCat={}; l.forEach(g=>{ const k=g.categoria||'Sin categoría'; porCat[k]=(porCat[k]||0)+g.monto+g.iva; }); const mxc=Math.max(1,...Object.values(porCat));
  const meses=[...new Set(l.map(g=>g.fecha.slice(0,7)))]; const nomMes=m=>{ const t=new Date(m+'-15T12:00').toLocaleDateString('es-AR',{month:'long',year:'numeric'}); return t.charAt(0).toUpperCase()+t.slice(1); };
  r.innerHTML=l.length?`<div class="grid g21 gastos"><div>${meses.map(m=>{ const g=l.filter(x=>x.fecha.startsWith(m)); return `<section class="grupo"><h2 class="gh">${nomMes(m)}<span class="gt">${money(g.reduce((a,x)=>a+x.monto+x.iva,0))}</span></h2><div class="filas">${g.map(x=>`<div class="fila click" data-act="gasto-edit" data-id="${x.id}"><span class="fd"><b>${x.fecha.slice(8)}</b>${new Date(x.fecha+'T12:00').toLocaleDateString('es-AR',{weekday:'short'}).replace('.','')}</span><div class="fm"><b>${esc(x.concepto)}</b><span>${[esc(x.categoria||''),esc(x.medio||''),x.iva?'IVA '+money(x.iva)+(x.ivaRec?' recuperable':''):''].filter(Boolean).join(' · ')}</span></div><div class="fn"><b>${money(x.monto+x.iva)}</b></div></div>`).join('')}</div></section>`; }).join('')}</div><aside class="card cats"><h2>Por categoría</h2><div class="big2">${money(tot)}</div><p class="sm muted mt0">${l.length} gasto${l.length>1?'s':''} con estos filtros</p>${Object.entries(porCat).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="hb"><span>${esc(k)}</span><div class="tr"><div class="fl" style="width:${v/mxc*100}%"></div></div><b>${money(v)}</b></div>`).join('')}</aside></div>`:vacioHtml('No hay gastos con esos filtros.'); };
AFTER.gastos=()=>FILL.gastos();
ACT['gasto-nuevo']=()=>gastoForm(null); ACT['gasto-edit']=el=>gastoForm(S.gastos.find(g=>g.id===+el.dataset.id));
let _gFut=null;
function gastoForm(g){ _gFut=null; const cs=[...new Set(S.gastos.map(x=>x.categoria).filter(Boolean).concat(['Alquiler','Servicios','Sueldos','Impuestos','Insumos','Mantenimiento','Varios']))];
  formModal(g?'Editar gasto':'Nuevo gasto',[{n:'fecha',l:'Fecha',t:'date'},{n:'concepto',l:'Concepto',t:'text',req:true},{n:'categoria',l:'Categoría',t:'text',list:cs},{n:'medio',l:'Se pagó con',t:'select',o:['Efectivo','Transferencia','Débito','Crédito','Otro']},{n:'monto',l:'Monto sin IVA ($)',t:'num',req:true,min:0},{n:'iva',l:'IVA ($)',t:'num',min:0},{n:'ivaRec',l:'El IVA es recuperable (crédito fiscal)',t:'check',full:true}],g||{fecha:hoy(),medio:'Efectivo'},d=>{
    if(d.fecha&&d.fecha>hoy()&&_gFut!==d.fecha){ _gFut=d.fecha; throw new Error('La fecha ('+fechaTxt(d.fecha)+') es posterior a hoy. Si está bien, tocá «Guardar» otra vez.'); } _gFut=null;
    if(g) Object.assign(g,d); else S.gastos.push(Object.assign({id:sig('G')},d)); guardar(); cerrar(); refrescar(); toast('Gasto guardado'); },{foot:g?`<button class="btn bad sm" type="button" data-act="gasto-del" data-id="${g.id}">Eliminar</button><span class="grow"></span>`:''}); }
ACT['gasto-del']=el=>confirmar('¿Eliminar este gasto?',()=>{ S.gastos=S.gastos.filter(g=>g.id!==+el.dataset.id); guardar(); refrescar(); toast('Gasto eliminado'); },'Eliminar');

