function periodo(){ const h=hoy(),R=UI.rep; const d=new Date(); const ini=ymd(new Date(d.getFullYear(),d.getMonth(),1)); const iniP=ymd(new Date(d.getFullYear(),d.getMonth()-1,1)); const finP=ymd(new Date(d.getFullYear(),d.getMonth(),0));
  return {hoy:[h,h],'7d':[addDias(h,-6),h],mes:[ini,h],ant:[iniP,finP],'30d':[addDias(h,-29),h],custom:[R.desde||h,R.hasta||h]}[R.per]; }
VIEWS.reportes=function(){ const R=UI.rep;
  return `${encab('Reportes','',`<label class="ccper">Período<select data-bind="rep.per">${opts([{v:'hoy',t:'Hoy'},{v:'7d',t:'Últimos 7 días'},{v:'mes',t:'Este mes'},{v:'ant',t:'Mes anterior'},{v:'30d',t:'Últimos 30 días'},{v:'custom',t:'Personalizado'}],R.per)}</select></label><button class="btn" data-act="rep-csv">Exportar ventas (CSV)</button>`)}
  ${R.per==='custom'?`<div class="filters"><label class="field">Desde<input type="date" data-bind="rep.desde" value="${esc(R.desde)}"></label><label class="field">Hasta<input type="date" data-bind="rep.hasta" value="${esc(R.hasta)}"></label></div>`:''}<div id="res"></div>`; };
FILL.reportes=function(){ const r=$('#res'); if(!r) return; const [d,h]=periodo(); const R=reporte(d,h); const n=difDias(h,d)+1, A=reporte(addDias(d,-n),addDias(d,-1)), vs='vs. '+n+(n===1?' día anterior':' días anteriores');
  if((UI.rep.per==='custom')!==!!document.querySelector('[data-bind="rep.desde"]')){ render(); return; }
  const pr=R.prods.map(p=>({...p,gan:p.ing-p.cst})).sort((a,b)=>b.gan-a.gan); const mx=Math.max(1,...pr.map(p=>p.gan));
  const desde30=addDias(hoy(),-30); const vend=new Set(); S.ventas.forEach(v=>{ if(v.estado!=='Anulada'&&v.fecha>=desde30) v.items.forEach(i=>vend.add(i.productoId)); });
  const parado=S.productos.filter(p=>p.activo&&stockDe(p.id)>0&&!vend.has(p.id)); const valorParado=parado.reduce((a,p)=>a+stockDe(p.id)*p.costo,0);
  r.innerHTML=`<div class="ccstrip lstrip"><span>Del <b>${fechaTxt(d)}</b> al <b>${fechaTxt(h)}</b></span><span class="dot"></span><span><b>${R.vs.length}</b> venta${R.vs.length===1?'':'s'}</span></div>
  <div class="kpis k6"><div class="kpi"><div class="k">Ventas</div><div class="v">${money(R.ingresos)}</div><div class="d">${delta(R.ingresos,A.ingresos,vs,false,addDias(d,-n))}</div></div><div class="kpi"><div class="k">Costo de la mercadería vendida</div><div class="v">${money(R.costo)}</div></div><div class="kpi good"><div class="k">Margen bruto</div><div class="v">${money(R.bruto)}</div><div class="d">${R.ingresos>0?fmt(R.bruto/R.ingresos*100,1)+'% de las ventas':''}</div></div>
   <div class="kpi"><div class="k">Gastos</div><div class="v">${money(R.gastos)}</div><div class="d">${delta(R.gastos,A.gastos,vs,true,addDias(d,-n))}</div></div><div class="kpi ${R.mermas>0?'warn':''}"><div class="k">Mermas</div><div class="v">${money(R.mermas)}</div><div class="d">valorizadas a costo</div></div><div class="kpi ${R.neto>=0?'good':'bad'}"><div class="k">Resultado</div><div class="v">${money(R.neto)}</div><div class="d">${delta(R.neto,A.neto,vs,false,addDias(d,-n))||"margen bruto − gastos − mermas"}</div></div></div>
  <div class="grid g2"><div class="card"><h2>Productos que más ganancia dejan</h2>${pr.length?`<div class="tw"><table><thead><tr><th>Producto</th><th class="n">Vendido</th><th class="n">Ventas</th><th class="n">Ganancia</th><th class="n">Margen</th></tr></thead><tbody>${pr.slice(0,12).map(p=>`<tr><td>${esc(p.nombre)}</td><td class="n">${p.unidad==='kg'?fmt(p.cant,2)+' kg':fmt(p.cant,0)}</td><td class="n">${money(p.ing)}</td><td class="n b">${money(p.gan)}</td><td class="n">${p.ing>0?fmt(p.gan/p.ing*100,0)+'%':'—'}</td></tr>`).join('')}</tbody></table></div>`:vacioHtml('Sin ventas en el período.')}</div>
  <div class="card"><h2>Por categoría</h2>${Object.keys(R.cats).length?Object.entries(R.cats).sort((a,b)=>b[1].ing-a[1].ing).map(([k,v])=>`<div class="hb"><span>${esc(k)}</span><div class="tr"><div class="fl" style="width:${v.ing/Math.max(1,R.ingresos)*100}%"></div></div><b>${money(v.ing)}</b></div>`).join(''):vacioHtml('Sin datos.')}
   <h2 style="margin-top:16px">Medios de pago</h2>${Object.keys(R.medios).length?Object.entries(R.medios).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="hb"><span>${esc(k)}</span><div class="tr"><div class="fl" style="width:${v/Math.max(1,R.ingresos)*100}%"></div></div><b>${money(v)}</b></div>`).join(''):vacioHtml('Sin datos.')}</div></div>
  <div class="card"><h2>Stock sin movimiento en 30 días</h2><p class="sm muted mt0">Plata inmovilizada en productos que no se vendieron en el último mes: <b>${money(valorParado)}</b>. Pensá en promociones o en no volver a comprarlos.</p>${parado.length?`<div class="tw"><table><thead><tr><th>Producto</th><th class="n">Stock</th><th class="n">Valor a costo</th></tr></thead><tbody>${parado.sort((a,b)=>stockDe(b.id)*b.costo-stockDe(a.id)*a.costo).slice(0,10).map(p=>`<tr><td>${esc(p.nombre)}</td><td class="n">${qtyTxt(p,stockDe(p.id))}</td><td class="n">${money(stockDe(p.id)*p.costo)}</td></tr>`).join('')}</tbody></table></div>`:vacioHtml('Todo lo que tenés en stock se vendió en el último mes.')}</div>`; };
AFTER.reportes=()=>FILL.reportes();
ACT['rep-csv']=()=>{ const [d,h]=periodo(); const rows=[]; ventasValidas(d,h).forEach(v=>v.items.forEach(i=>rows.push([v.id,v.fecha,v.hora||'',cliNom(v.clienteId),v.medio,i.nombre,String(i.cant).replace('.',','),String(i.precio).replace('.',','),String(i.costo).replace('.',','),String(r2(i.cant*i.precio)).replace('.',',')])));
  if(!rows.length){ toast('No hay ventas en el período.',true); return; } descargar('ventas_'+d+'_a_'+h+'.csv',aCSV(['venta','fecha','hora','cliente','medio de pago','producto','cantidad','precio','costo','subtotal'],rows)); };

/* ================= AJUSTES ================= */
ACT['aj-ir']=el=>{ const s=document.getElementById(el.dataset.v); if(s){ s.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'}); document.querySelectorAll('.ajidx button').forEach(b=>b.classList.toggle('on',b===el)); } };
VIEWS.ajustes=function(){ const c=S.config; const ur=c.ultimoRespaldo;
  return `${encab('Ajustes','')}<div class="ajustes"><nav class="ajidx" aria-label="Secciones de ajustes">${[['aj-neg','Negocio'],['aj-apa','Apariencia'],['aj-bal','Balanza'],['aj-res','Respaldo'],['aj-dat','Datos']].map(([i,t],k)=>`<button type="button" data-act="aj-ir" data-v="${i}" class="${k?'':'on'}">${t}</button>`).join('')}</nav><div class="ajcol">
  ${S._guardadoOk===false?'<div class="banner warn"><span><b>Este navegador no está guardando los datos.</b> Hacé un respaldo ahora y revisá que el navegador permita almacenamiento local.</span></div>':''}
  <div class="card" id="aj-neg"><h2>Negocio</h2><form id="cfg" class="frm" autocomplete="off"><label class="field">Nombre<input name="nombre" value="${esc(c.nombre)}"></label><label class="field">Subtítulo<input name="sub" value="${esc(c.sub||'')}"></label>
   <label class="field">Rubro (ajusta módulos)<select name="rubro" data-chg="rubro">${opts(Object.keys(RUBROS),c.rubro)}</select></label><label class="field">Moneda<input name="moneda" value="${esc(c.moneda)}"></label>
   <label class="field inline"><input type="checkbox" name="venc" ${c.venc?'checked':''}> Controlar vencimientos y lotes</label><label class="field inline"><input type="checkbox" name="peso" ${c.peso?'checked':''}> Vendo productos al peso (kg)</label>
   <label class="field">IVA habitual en compras (%)<input name="iva" value="${fnum(c.iva)}" inputmode="decimal"></label><label class="field">Avisar vencimientos con (días)<input name="diasVence" value="${c.diasVence}" inputmode="numeric"></label><label class="field">Precio desactualizado después de (días)<input name="diasPrecio" value="${c.diasPrecio}" inputmode="numeric"></label>
   <label class="field">Logo de tu negocio (opcional)<input type="file" id="logof" accept="image/*"></label></form><div class="bar mt12"><button class="btn pri" data-act="cfg-guardar">Guardar ajustes</button><button class="btn" data-act="logo-reset">Quitar logo</button></div></div>
  <div class="card" id="aj-apa"><h2>Apariencia</h2><p class="sm muted mt0">Se aplica sólo en este dispositivo. En Automático sigue el modo claro u oscuro del sistema.</p><div class="seg tema" role="group" aria-label="Tema">${[["claro","Claro"],["oscuro","Oscuro"],["auto","Automático"]].map(([v,t])=>`<button type="button" data-act="tema" data-v="${v}" aria-pressed="${temaActual()===v}" class="${temaActual()===v?"on":""}">${t}</button>`).join("")}</div></div>
  ${(()=>{ const b=c.balanza; return `<div class="card" id="aj-bal"><h2>Balanza con etiquetas</h2><p class="sm muted mt0">Si tu balanza (Systel, Kretz, etc.) imprime etiquetas con código de barras, al escanearlas en Ventas se carga el producto con su peso. Cada producto necesita su <b>PLU de balanza</b> en la ficha. Los datos del formato están en el manual o en la configuración de la balanza.</p>
   <form id="bal" class="frm" autocomplete="off"><label class="field inline full"><input type="checkbox" name="on" ${b.on?'checked':''}> Leer etiquetas de balanza al vender</label>
   <label class="field">Prefijos de la etiqueta<input name="prefijos" value="${esc(b.prefijos)}" placeholder="20"><span class="muted hint">Los 2 primeros dígitos del código. Varios separados por coma: 20, 21</span></label>
   <label class="field">Largo del PLU<select name="largoPlu">${opts([{v:5,t:'5 dígitos'},{v:4,t:'4 dígitos'}],b.largoPlu)}</select></label>
   <label class="field">La etiqueta trae<select name="valor">${opts([{v:'peso',t:'El peso en gramos'},{v:'precio',t:'El importe a cobrar'}],b.valor)}</select></label>
   <label class="field">Decimales del importe<select name="decimales">${opts([{v:0,t:'Sin decimales ($ 1234)'},{v:1,t:'1 decimal ($ 123,4)'},{v:2,t:'2 decimales ($ 12,34)'}],b.decimales)}</select></label>
   <label class="field full">Probar con un código<input id="balt" data-live="bal-test" placeholder="Escaneá o escribí el código de una etiqueta" inputmode="numeric"></label><div id="balr" class="chk full"></div></form>
   <div class="bar mt12"><button class="btn pri" data-act="bal-guardar">Guardar balanza</button></div></div>`; })()}
  <div class="grid g2" id="aj-res"><div class="card"><h2>Respaldo</h2><p class="sm muted mt0">Tus datos se guardan en este navegador. Si borrás los datos del navegador o cambiás de computadora se pierden, por eso hay que respaldarlos seguido. ${(()=>{ const n=adjUsados().size; return n?'El respaldo incluye los <b>'+n+' archivo'+(n>1?'s':'')+'</b> adjuntos (comprobantes y archivos de clientes). ':''; })()}${ur?'Último respaldo: <b>'+fechaTxt(ur)+'</b>.':'<b>Todavía no hiciste ninguno.</b>'}</p>
   <div class="bar"><button class="btn pri" data-act="resp-exp">Descargar respaldo</button><label class="btn">Restaurar respaldo<input type="file" id="respf" accept=".json" hidden></label></div></div>
   <div class="card"><h2>Pasar los datos del programa anterior</h2><p class="sm muted mt0">Elegí el archivo <b>gestion.json</b> de la carpeta «Datos» del programa de escritorio. Se importan productos, proveedores, precios, compras, gastos y movimientos de stock. <b>Reemplaza los datos actuales.</b></p>
   <label class="btn">Elegir gestion.json<input type="file" id="gestf" accept=".json" hidden></label><div id="gestr" class="sm mt8"></div></div></div>
  <div class="card" id="aj-dat"><h2>Datos</h2><div class="bar"><button class="btn" data-act="demo-cargar">Cargar datos de ejemplo</button><button class="btn bad" data-act="vaciar">Empezar con datos vacíos</button></div><p class="sm muted">${S.config.demo?'Ahora estás viendo datos de ejemplo. Cuando quieras empezar en serio, usá «Empezar con datos vacíos» o importá tu gestion.json.':''}</p></div></div></div>`; };
CHG.rubro=el=>{ aplicarRubro(el.value); const f=$('#cfg'); f.elements.venc.checked=S.config.venc; f.elements.peso.checked=S.config.peso; };
ACT['cfg-guardar']=()=>{ const f=$('#cfg').elements; const c=S.config; const iva=num(f.iva.value),dv=num(f.diasVence.value),dp=num(f.diasPrecio.value);
  if(iva==null||dv==null||dp==null||!f.nombre.value.trim()){ toast('Revisá el nombre y los números.',true); return; }
  Object.assign(c,{nombre:f.nombre.value.trim(),sub:f.sub.value.trim(),rubro:f.rubro.value,moneda:f.moneda.value.trim()||'$',venc:f.venc.checked,peso:f.peso.checked,iva,diasVence:Math.round(dv),diasPrecio:Math.round(dp)}); guardar(); pintarMarco(); render(); toast('Ajustes guardados'); };
function leerBal(){ const f=$('#bal').elements; return {on:f.on.checked,prefijos:f.prefijos.value.trim()||'20',largoPlu:+f.largoPlu.value,valor:f.valor.value,decimales:+f.decimales.value}; }
ACT['bal-guardar']=()=>{ const b=leerBal(); if(!/^\d{2}(\s*,\s*\d{2})*$/.test(b.prefijos)){ toast('Los prefijos tienen que ser de 2 dígitos, separados por coma (por ejemplo 20, 21).',true); return; } S.config.balanza=b; guardar(); toast('Balanza guardada'); LIVE['bal-test'](); };
LIVE['bal-test']=()=>{ const t=$('#balt'),r=$('#balr'); if(!t||!r) return; const v=t.value.replace(/\D/g,''); if(!v){ r.textContent=''; return; }
  const prev=S.config.balanza; S.config.balanza=Object.assign(leerBal(),{on:true}); let e; try{ e=leerEtiquetaBalanza(v); }finally{ S.config.balanza=prev; }
  if(v.length!==13){ r.innerHTML='<div class="info">El código tiene que tener 13 dígitos (lleva '+v.length+').</div>'; return; }
  if(!e){ r.innerHTML='<div class="bad">No empieza con ninguno de los prefijos configurados.</div>'; return; }
  const k=!e.ok?'bad':e.p?'good':'warn';
  r.innerHTML=`<div class="${k}">${e.ok?'':'El dígito verificador no coincide: revisá el código. '}PLU <b>${esc(e.plu)}</b> → ${e.p?'<b>'+esc(e.p.nombre)+'</b>':'ningún producto tiene ese PLU'} · ${e.valor==='peso'?'peso <b>'+qtyTxt({unidad:'kg'},e.kg)+'</b>':'importe <b>'+money2(e.importe)+'</b>'+(e.kg!=null?' = '+qtyTxt({unidad:'kg'},e.kg):'')}</div>`; };
ACT['logo-reset']=()=>{ S.config.logo=''; guardar(); pintarMarco(); toast('Logo quitado'); };
ACT['resp-exp']=async el=>{ if(el) el.disabled=true; const hay=adjUsados().size; if(hay) toast('Preparando el respaldo con '+hay+' archivo'+(hay>1?'s':'')+'…');
  let r; try{ r=await exportarConArchivos(); }catch(e){ r={txt:exportarJSON(),n:0,error:true}; } if(el) el.disabled=false;
  await descargar('respaldo_'+S.config.nombre.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/[^a-z0-9]+/g,'_')+'_'+hoy()+'.json',r.txt);
  if(r.error||r.faltan) toast('Ojo: '+(r.error?'no se pudieron leer los archivos':r.faltan+' archivo'+(r.faltan>1?'s no están':' no está')+' en este dispositivo')+'. El resto del respaldo se guardó.',true);
  setTimeout(()=>{ if(UI.vista==='ajustes') render(); },300); };
ACT['demo-cargar']=()=>confirmar('Se reemplazan los datos actuales por los de ejemplo. ¿Seguir?',()=>{ cargarDemo(); pintarMarco(); render(); toast('Datos de ejemplo cargados'); },'Cargar ejemplo',false);
ACT.vaciar=()=>confirmar('Se borran <b>todos</b> los productos, ventas, compras y clientes. Esto no se puede deshacer. Si no hiciste un respaldo, hacelo antes.',()=>{ const c=S.config; S=vacio(); S.config=Object.assign(S.config,c,{demo:false}); indexar(); guardar(); pintarMarco(); ir('panel'); render(); toast('Listo, empezás de cero'); },'Borrar todo');
document.addEventListener('change',e=>{ const el=e.target;
  if(el.id==='respf'&&el.files[0]){ const rd=new FileReader(); rd.onload=()=>confirmar('Se reemplazan los datos actuales por los del respaldo. ¿Seguir?',async()=>{ try{ const adj=importarJSON(String(rd.result)); pintarMarco(); render();
      if(adj&&adj.length){ toast('Restaurando '+adj.length+' archivo'+(adj.length>1?'s':'')+'…'); const n=await restaurarAdjuntos(adj); toast('Respaldo restaurado con '+n+' archivo'+(n!==1?'s':''),n<adj.length); render(); }
      else toast('Respaldo restaurado'); }catch(err){ toast(err.message,true); } },'Restaurar',false); rd.readAsText(el.files[0]); el.value=''; }
  if(el.id==='gestf'&&el.files[0]){ const rd=new FileReader(); rd.onload=()=>{ let o; try{ o=JSON.parse(String(rd.result).replace(/^﻿/,'')); }catch(err){ $('#gestr').innerHTML='<span class="dn">El archivo no es un JSON válido.</span>'; return; }
      if(!o||(!o.Productos&&!o.Proveedores)){ $('#gestr').innerHTML='<span class="dn">No parece un gestion.json del programa anterior.</span>'; return; }
      confirmar('Se reemplazan los datos actuales por los del programa anterior ('+(o.Productos||[]).length+' productos). ¿Seguir?',()=>{ try{ const r=importarGestion(o); pintarMarco(); ir('productos'); abrir('Importación lista','<p class="mt0">Se importaron <b>'+r.productos+' productos</b>, '+r.proveedores+' proveedores, '+r.compras+' compras y '+r.movimientos+' movimientos de stock.</p><p class="muted">El programa anterior no distinguía unidades: todos los productos quedaron «por unidad». Los que vendés al peso pasalos a kg con el botón <b>Unidad por categoría</b> o desde la ficha de cada uno.</p>',{foot:'<button class="btn pri" data-act="cerrar">Entendido</button>'}); }catch(err){ toast('No se pudo importar: '+err.message,true); } },'Importar',false); }; rd.readAsText(el.files[0]); el.value=''; }
  if(el.id==='logof'&&el.files[0]){ const rd=new FileReader(); rd.onload=()=>{ const im=new Image(); im.onload=()=>{ const s=192,cv=document.createElement('canvas'); cv.width=cv.height=s; const x=cv.getContext('2d'); const m=Math.min(im.width,im.height); x.drawImage(im,(im.width-m)/2,(im.height-m)/2,m,m,0,0,s,s); S.config.logo=cv.toDataURL('image/png'); guardar(); pintarMarco(); toast('Logo actualizado'); }; im.onerror=()=>toast('No pude leer esa imagen.',true); im.src=String(rd.result); }; rd.readAsDataURL(el.files[0]); el.value=''; } });

/* ================= ARRANQUE ================= */
window.addEventListener('hashchange',()=>{ const v=location.hash.slice(1); if(VIEWS[v]){ UI.vista=v; render(); } });
// arranca cuando ya se cargaron todos los scripts (comprobantes, etiquetas, archivos)
document.addEventListener('DOMContentLoaded',function arrancar(){
  const c=cargar();
  if(c.o){ S=prepararEstado(c.o); indexar(); }
  else if(c.raw) S=datosDanados(c.raw); // hay datos guardados que no se pueden leer: no se pisan
  else cargarDemo();
  if(!c.raw) restaurarCarrito();
  const v=location.hash.slice(1); if(VIEWS[v]) UI.vista=v;
  pintarMarco(); render(); if(c.raw) avisoDanados(); });
// Datos guardados que no se pueden leer: se copian aparte y se arranca vacío sin borrar nada.
// Si no hay lugar para la copia, no se guarda nada hasta descargarla.
let _danado=null;
function datosDanados(raw){ _danado={raw,clave:LS_KEY+'_danado_'+hoy()};
  try{ localStorage.setItem(_danado.clave,raw); _danado.copia=true; }catch(e){ _danado.copia=false; BLOQUEO=true; }
  const s=vacio(); S=s; indexar(); return s; }
function avisoDanados(){ abrir('No pude leer tus datos',`<p class="mt0">Los datos guardados en este navegador están dañados y no se pueden abrir. <b>No borré nada:</b> ${_danado.copia?'guardé una copia aparte':'todavía no pude guardar una copia, así que <b>no se va a guardar nada</b> hasta que la descargues'}.</p>
  <p>Para seguir trabajando, restaurá tu último respaldo desde <b>Ajustes → Restaurar respaldo</b>. Descargá también la copia de los datos dañados: con ella se pueden intentar recuperar.</p>`,
  {foot:`<button class="btn" id="dnd">Descargar copia dañada</button><button class="btn pri" data-act="go" data-v="ajustes" id="dnaj">Ir a Ajustes</button>`});
  $('#dnd').onclick=async()=>{ await descargar('datos_danados_'+hoy()+'.json',_danado.raw); if(BLOQUEO){ BLOQUEO=false; guardar(); toast('Copia descargada. Ya se vuelve a guardar.'); } };
  $('#dnaj').addEventListener('click',()=>cerrar()); }
